quests[265] = { id = 265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadowy Search Continues", description = "Here is your book back, {name}, and I bid you fortune with your search.  If you ask others in town, perhaps they can offer you more clues.\n\nAnd here is one more for you - although the author of this book is a stranger to Darkshire, the book itself was purchased here.", progress = "Sometimes I'll sell blank books to scholars and mages, or to anyone who wants to keep a journal.\n\nI remember well everyone to whom I sold a book within the last few months...", completion = "Ah, yes.  I sold this book a month ago to a shady person.  He didn't tell me his name, but he was a nervous, jittery chap, always looking over his shoulder.\n\nI hope that helps you...", objectives = "See if other townsfolk have clues about the shadowy figure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[266] = { id = 266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inquire at the Inn", description = "Here is your book, and good luck with your inquiries.\n\nYou might want to expand your search to the inn.  If the person whom you seek spent time in town, then chances are someone saw him there.", progress = "The Scarlet Raven doesn't see the business it used to, but we still do get travelers passing through.\n\nIf you can describe the person you're looking for, maybe I'll remember him.", completion = "Oh yeah, I remember this book.  Its owner rented a room for a few days, and spent his nights at the bar, writing.\n\nHe left town in a hurry, muttering about being hunted by...something.  Last I saw him he was heading west out of town, looking for a new spot to hide.\n\nThe first place he'd find to the west is Raven Hill...", objectives = "Search the inn for clues about the shadowy figure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[267] = { id = 267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trogg Threat", description = "{class}, you may or may not be aware of the Trogg threat looming over Dwarven lands.  With the Ironforge Reserve called up to the Alliance Front, we are left with a fraction of the defense forces needed to keep these lands safe.  My regiment is assigned to watch over the Gate here and we cannot leave our post for fear of invasion.\n\nBut we need some pressure put on those damned Troggs lurking in the hills.  If you're up to the task, wage an assault on the Troggs.  Bring me back 8 Trogg Stone Teeth as proof.", progress = "Do you have 8 Trogg Stone Teeth to show me?  If not, there is still work to be done, {name}.", completion = "I am quite impressed, {name}.  You have done the Dwarven race a great favor by defending our lands.  King Magni Bronzebeard himself would be proud!", objectives = "Bring 8 Trogg Stone Teeth to Captain Rugelfuss in the southern guard tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[268] = { id = 268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Sven", description = "The book you found was only half finished.  I had to leave it at Sven's farm when I fled there...\n\nHere.  Take my completed journal to Sven.  It describes more fully what happened at his farm.\n\nAlthough this journal has been my only company these past weeks, if giving it up keeps me from having to face Sven and his wrath, then I do it willingly!", progress = "Did you find who the Shadowy Figure was?", completion = "This journal explains much to me, and sets me on the path against the dark riders!  I have seen these riders in Duskwood, and have seen them speak with the wizard Morbent Fel, at the Forlorn Rowe.", objectives = "Return to Sven with Jitters' completed journal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[269] = { id = 269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Wisdom", description = "Go to the city of Stormwind and speak with Bishop Farthing in the Cathedral of Light.  Give him Jitters' journal and tell him you mean to face Morbent Fel.\n\nAlthough Stormwind has forsaken Darkshire, Farthing is a kind soul and very wise.  He may help you on your quest to save us.\n\nYour mission is perilous, but hurry, {name}.  With each passing hour, the shadows of Duskwood grow ever darker.", progress = "Rest, brother.  I can tell you have traveled far, and you bear a heavy burden.  Can you tell me what casts that dark shadow over you?", completion = "<After reading the journal and hearing your intent...>\n\nAn evil taint has gained a foothold within the already beleaguered Duskwood.  I thank the Light we have a hero such as you to face it.\n\nBut you must first prepare yourself for the coming trial...for the Necromancer Morbent Fel is immensely powerful, and has cast dark enchantments about himself to protect him from physical assaults.  If you are to defeat him, you will need a weapon that is proof against these protections.", objectives = "Give Jitters' Completed Journal to Bishop Farthing in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[270] = { id = 270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Doomed Fleet", description = "Years ago, the Third Fleet of Kul'Tiras sunk along the coasts of The Wetlands, an expanse of marsh north of the Dwarven kingdom of Ironforge.  Aboard one ship was a load of Lightforge Iron.\n\nThis metal is precious to us, for items crafted from it strike with holy truth.  If you are to face Morbent Fel, then you will need such a weapon.\n\nGo to Menethil Harbor and speak with my dwarven colleague Glorin Steelbrow.  If that lost metal can be found, he'll know where to look.", completion = "Lightforge Iron is a precious metal, but it sounds like your quest is a dire one.  You've come a long way, Brother.  With luck, you might just find what you seek!\n\nAnd if you do get the iron, I know who can fashion it into a weapon against this Necromancer you speak of in Duskwood.", objectives = "Go to Menethil Harbor in the Wetlands, and speak with Glorin Steelbrow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[271] = { id = 271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyrin's Revenge", description = "I don't suppose you'd be interested in a little payback for His Boldness? Daryl does have some skill, it pains me to say.\n\nA year ago, a large bear had been the target of the Farstrider Lodge, but none of the hunters had any luck with him. So, Daryl thought he'd try his hand against him. All he had to show for his effort was that ugly scar over his eye.\n\nKill the bear, and I'm sure even Daryl would be speechless for once.\n\nThe bear, Ol' Sooty, can be found around his lair in the hills over Thelsamar.", progress = "Ah, {name}! Back so soon? No doubt you've been at the hunt again? Don't worry if you've had some setbacks, in the long run it will make you better!\n\n...You couldn't get much worse, anyway...", completion = "Er... what's this? A bear's head, by the looks at it.\n\n<He runs a finger along his scar unconsciously.>\n\nWell, that's quite an interesting kill you have yourself there. Couldn't be that bear from back then...\n\n<He trails off then starts to visibly shake.>\n\nOh, take that away take it away! Get that grisly thing out of here!", objectives = "Kill Ol' Sooty then show your handiwork to Daryl the Youngling at the Farstrider Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[272] = { id = 272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of the Sea Lion", description = "For the second trial, you'll need the two halves that make the Pendant of the Sea Lion.  One half draws power from the agility of the sea lion aspect, gliding through water; the other draws power from the incredible endurance of the sea lion aspect.  Druids draw on both these traits equally to embody the aspect of their aquatic form.\n\nSpeak with the locals of Moonglade to learn where the parts may lie, and bring both here to join them together.  Once formed, take the pendant to Dendrite Starblaze.", progress = "Have you formed your pendant for me to inspect, {name}?  If you need help in locating the parts, try asking the local populace for information.  Not only will you find what you seek, but it will give you a reason to explore this wondrous and sacred glade.", completion = "You've completed the Trial of the Sea Lion, {name} - congratulations.\n\nEach task in acquiring the pendant shows that both agility and endurance are necessary to act in harmony with what you desire to do underwater.  Neither can exist without the other, and both cannot be done without your willingness to embrace the aspect of the sea lion.\n\nRemember these lessons well, and count on them once you have gained your aquatic form.", objectives = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance. Speak with the residents of Moonglade to learn clues as to where these items may be located.\n\nForm the Pendant of the Sea Lion from the two pendant halves. You need to be in proximity of the Shrine of Remulos to do this.\n\nBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[273] = { id = 273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resupplying the Excavation", description = "It's not too late though, you're welcome to go look for Huldar. He can't have made it very far, strong as they are, Miran and Saean can only move so fast laden down with those barrels.\n\nThey're taking the normal route to the site, leaving south out of town and following the curve of the Loch.\n\nShouldn't have a problem finding them unless they've already gotten there.", completion = "Hmph, it'll take more than a Dark Iron ambush to stop the deliveries!\n\nBut Saean... I would never have suspected him to be one of their sympathizers. We've been working with him for almost a year now... maybe I missed the signs.\n\nWell, I'll consider that later.", objectives = "Speak with Huldar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[274] = { id = 274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dark Threat Looms", description = "This ain't no ordinary blast powder.  Look at the tiny silver crystals.  And the distinct smell!  Why it's clear as daylight that this is Seaforium Powder.  Seaforium is harmless enough.  But once it's wet it could blow Ironforge out of the mountain.\n\nThe chemical reaction can be defused by mixing four components:  lurker venom, crushed Mo'Grosh crystal, a crocolisk tear and this disarming colloid.  Now tell Hinderweir before it's too late!", progress = "What is that you bring from Ashlan?", completion = "A disarming colloid? For Seaforium?  Oh heavens!", objectives = "Ashlan Stonesmirk wants you to return to Chief Engineer Hinderweir and inform him of the new discovery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[275] = { id = 275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blisters on The Land", description = "I do not know why, but a festering grows within the Wetlands.  Fen Creepers have risen.  They are diseased, fevered blisters on the land, and for the fever to break they must be dispatched and allowed to settle back into the marshes.\n\nThe Fen Creepers shamble amidst the waterways of the Wetlands.", progress = "The Wetlands still weep, and the Fen Creepers still rage.  Return to me when your task is done.", completion = "This land is soothed by your efforts, and for this I will grant you a boon.", objectives = "Kill 12 Fen Creepers, then return to Rethiel the Greenwarden in the Wetlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[276] = { id = 276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tramping Paws", description = "The Mosshide Gnolls have lived in the Wetlands peacefully for many years, but now grow in numbers.  Their feet stamp flat the fen's bushes and flowers, and their foul axes cut too much wood to fuel their fires.\n\nThey are no longer in balance with the land.  For the Wetlands to survive, the Gnolls must be reduced.\n\nKill 15 Mosshide Gnolls and 10 Mosshide Mongrels.  Hunt them to the south, near the Dwarven gate of Algaz.  After you do this, return to me.", progress = "Your task is still at hand, young {class}.", completion = "By reducing the Gnolls' number, you have tended to the health of the Wetlands.  Although my faith in your people has been taxed in the past, {race}, it may yet be restored.", objectives = "Kill 15 Mosshide Gnolls and 10 Mosshide Mongrels, then return to Rethiel the Greenwarden in the Wetlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[277] = { id = 277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Taboo", description = "The Mosshides are cutting the trees of the Wetlands, using the trees' flesh to warm themselves with fire.  I will suffer this pain no longer!\n\nRid the Mosshides of their crude flints, the tools they use to make fire.  The flints are borne by all Mosshides except the smaller Mosshide gnolls and Mosshide mongrels.", progress = "Do you have the Gnolls' tools for fire?", completion = "... thank you.  I will smash these flints and cast them into the sea, so that they may never again be used to burn living wood.", objectives = "Bring Rethiel the Greenwarden 9 Crude Flints.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[278] = { id = 278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dark Threat Looms", description = "Begin collecting the disarming materials immediately, {name}.  Lurker Venom can be found on the indigenous spiders in Loch Modan.  Crocolisk tears are found here in the Loch as well.  But a Mo'Grosh crystal will be very difficult to procure.  The ogres to the northeast mine them but the crystals are a very rare commodity.\n\nWe need to be prepared to defuse a Dark Iron attack!  Return to me once you've collected the needed items and I will prepare the mixture.", progress = "Do you have the needed items?  Time is of the essence!!", completion = "Just in time, {name}!", objectives = "Chief Engineer Hinderweir wants you to gather Lurker Venom, a Mo'grosh Crystal, and a Crocolisk Tear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[279] = { id = 279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claws from the Deep", description = "Murlocs are crawling out from the deep waters and building their villages on the coastline.  They are harassing our fishers and merchants and must be stopped.\n\nOne of these Murlocs, Gobbler, skulks with other Bluegill Murlocs and harries merchants along the road, always then retreating to the safety of the nearby Murloc hovels.  Our merchants are in jeopardy, and we will pay to secure them.\n\nGobbler prowls the river inlet north of here.  Find him, slay his kin, and bring me his head.", progress = "Our merchants will not be safe until we are rid of Gobbler and those Murlocs.", completion = "Ah, well done {name}.\n\nAccept this as payment for fulfillment of your contract with the Merchant Marines.", objectives = "Kill 12 Bluegill Murlocs.\n\nSlay Gobbler and take his head.\n\nBring Gobbler's Head to Karl Boran in Menethil Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[280] = { id = 280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dark Threat Looms", description = "Earlier today I spotted some Dark Iron Insurgents swimming toward the Dam with a large keg.  No Mountaineers were on hand to stop them!  I'm afraid they've planted the Seaforium at the base of the Dam and it could blow at any minute!  Let me combine all these ingredients into the Disarming Mixture.  There we go.\n\nNow I need you to take this mixture and stir it into the keg before it's too late!  Hurry!", progress = "The top of the keg slowly twists off.", completion = "The keg fizzles slightly as the Disarming Mixture settles in.", objectives = "Chief Engineer Hinderweir wants you to swim down to the base of the dam, locate the powder keg and stir in the Disarming Mixture to prevent an explosion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[281] = { id = 281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Goods", description = "Not long ago a merchant vessel, the Blind Princess, was raided by Murlocs.  Although the ship escaped intact, much of its cargo was dragged overboard by the creatures, including a very valuable statuette of Terenas Menethil.  We want that statuette recovered.\n\nSearch the coastal Murloc hovels for crates, barrels and other evidence of lost cargo.  Find the Menethil Statuette and return it to me.", completion = "This crate is covered with clawed scratches, and the marks of water damage.  Prying it open reveals soggy and rotted straw, as if something of value was stored in the crate.  You search through the straw...\n\n...and find an armload of red-colored bottles.", objectives = "Search the crates and barrels at the coastal Murloc camps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[282] = { id = 282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Senir's Observations", description = "I was planning on sending my apprentice to my brother Senir with my report, but I would feel much better were it placed in more... reliable hands. That is, of course, if you wouldn't mind?\n\nHmm... you'll have to take the tunnel to get to Kharanos.\n\nSpeak with Mountaineer Thalos before going through the tunnel. It's completely infested with troggs now.\n\nFollow the road back to Anvilmar, then keep heading east to the tunnel, Thalos is stationed nearby.", progress = "Hail! Have a care, {name}, the tunnel to Dun Morogh is infested with troggs and is not safe for travel.\n\nIf you haven't any pressing business in Dun Morogh, I'll have to ask you to remain in Anvilmar until the tunnel is safer.", completion = "Hm, well, if Whitebeard is sending you to Dun Morogh on important business, I can't very well stop you, can I?\n\nAt least let me provide you with some advice and directions.", objectives = "Speak with Mountaineer Thalos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[283] = { id = 283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dark Threat Looms", description = "The keg fizzles slightly.", completion = "Thank you so much, {name}!! You have saved the Stonewrought Dam!  Without your help, the Dark Iron terrorists would have surely seen to this mighty landmark's demise.  You have made the Kingdom and the Alliance proud, brave {class}.\n\nThe Dam is once again safe. . . for the time being at least. . . .", objectives = "The Disarming Mixture seemed to take effect. Return to Chief Engineer Hinderweir to report the good news.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[284] = { id = 284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Search Continues", description = "You thoroughly search this cluster of Murloc hovels, and find no trace of the Menethil Statuette.\n\nPerhaps one of the two nearby hovels to the north and northeast will have more clues.", completion = "This barrel is largely untouched.  Prying it open...\n\n...you are assaulted by the pungent odor of cheese.  It's a little wet, but still tasty!", objectives = "Search for the Menethil Statuette.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[285] = { id = 285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Search More Hovels", description = "This grouping of Murloc hovels, after a thorough inspection, reveals nothing.\n\n...but you're certain that the next clue you find will be fruitful.\n\nOne of the hovels to the north must have the Menethil Statuette!", completion = "This barrel is halfway buried amidst the mud and grass ...", objectives = "Continue searching the Murloc hovels for the Menethil Statuette.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[286] = { id = 286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return the Statuette", description = "After pulling the barrel free from the muck and opening it, a silvery figurine is found packed in fine straw.  It depicts a young, long-haired Paladin with hammer upraised.\n\nThis must be the Menethil Statuette!  You must now return it to Karl Boran in Menethil Harbor.", progress = "Do you have the statuette?", completion = "The captain of the Blind Princess will be relieved to hear this precious cargo has been recovered.  You have well earned this payment for services rendered.\n\nIt is good to see dependable folk like you, especially in trying times such as these.", objectives = "Bring Karl Boran the Menethil Statuette.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[287] = { id = 287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostmane Hold", description = "I'm behind on my report, and could use your help, {name}. I just managed to find where the trolls are holed up, but I saw so many trolls, I was afraid to go in.\n\nHere's what I need... Go down to the cave, poke around inside, kill a few of the trolls, then come back here.\n\nTake the road north out of Kharanos, when you get to the bridge, follow the frozen river west until you reach Iceflow Lake. You'll find Brewnall Village on the west bank. The Hold is southwest of the village.", progress = "You can't find it? My directions were very clear! We don't have much time, you've got to hurry! Don't come back until you've found the cave.", completion = "Ah, {name}! I didn't think you'd have much trouble finding the place, my directions are excellent, you know...\n\nLet me just finish up my report then.\n\n\n\nThere! Well, haha, now this certainly is funny... I don't suppose, {name}, that you would mind doing one last favor for me?", objectives = "Explore Frostmane Hold, and kill 5 Frostmane Headhunters for Senir Whitebeard in Kharanos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[288] = { id = 288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Third Fleet", description = "I was once First Mate on the Wave Mistress, ship-of-the-line in the Kul Tiras Third Fleet.  The Doomed Fleet.  Doomed, for on its last voyage the fleet was attacked  by Red Dragons.  Dragons controlled by Orcs!\n\nWe didn't stand a chance against that dragonfire...and our fleet was burned and sunk off this here coast.  I'm the sole survivor of those poor vessels...\n\n...Oh, my head hammers and pounds!  I'll need a fresh drink if I'm to get a handle on this hangover and continue my tale.", progress = "Oh, I'm so very thirsty!  Won't you buy a drink for this poor, pathetic fool?", completion = "Ah!  That hits the spot, and loosens the tongue.  Thanks, mate!", objectives = "Buy First Mate Fitzsimmons a Flagon of Mead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[289] = { id = 289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cursed Crew", description = "<Bolstered, Fitzsimmons continues his tale...>\n\nI am the sole survivor of the ill-fated Third Fleet of Kul Tiras, wrecked off the coast to the north.  But although I'm the only member of the fleet still breathing, I'm not the only one still walking about!  For on one of our ships was hidden a great, and terrible treasure, and the eerie power of it keeps the souls of my brothers trapped within the ships' rotting hulls.\n\nBut if you can free some of my brothers, then perhaps you can break their curse.", progress = "In my dreams, I can sometimes hear the doomed moans of my brethren!  Please, good sir, free them from the bonds and quiet their cries.", completion = "My thanks to you, {name}.  And the gratitude of my cursed brethren goes to you as well.", objectives = "Kill 13 Cursed Sailors, 5 Cursed Marines and First Mate Snellig. Bring Snellig's Snuffbox to First Mate Fitzsimmons in Menethil Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[290] = { id = 290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lifting the Curse", description = "To break the curse and free all of my brethren, the...thing...stowed on my ship must be retrieved and cleansed!  I don't know what it was, but I do know that it was stored securely in the ship's strongbox, which Captain Halyndor lorded over.\n\nMy old captain is still in my dreams.  I know he walks my doomed ship, the Intrepid.  Get the key from him, and use it to open the Intrepid's strongbox.\n\nThen, after you have the cursed thing, bring it to the priest Glorin Steelbrow in town.", progress = "This chest is securely locked.", completion = "The key is rusted but it fits the lock neatly.", objectives = "Get the Intrepid Strongbox Key from Captain Halyndor.\n\nUse the key to open the Intrepid's Locked Strongbox.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[291] = { id = 291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reports", description = "Excellent! Take my report to Senator Barin Redstone. He's a sour type, so don't let his less-than-sunny disposition get to you. He's in Ironforge, in the chamber where King Magni holds court.\n\nDon't know the way to Ironforge? Take the road out of Kharanos north, cross the bridge, then follow the road east--there are large banners flanking the road--up the mountainside.\n\nBy the way, if you might avoid mentioning how you assisted me? Can't let them think I'm not working hard out here, you know?", progress = "Hmm... it would seem that my guards are becoming less discriminatory with petitioners. Well, what do you want? Make it quick.", completion = "<He quickly peruses the report.>\n\nAuthority of the KING!? Has Magni taken complete leave of his senses! And that damnable Whitebeard... Taken matters into his own hands, has he? The Senate will not be pleased to hear about this, not one bit.\n\nWhat, are you still here? Go, before I call the guards!", objectives = "Deliver Senir's report to Senator Barin Redstone in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[292] = { id = 292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Paleth", description = "Opening the chest reveals a blackened orb, pulsing with an eerie light.  It is the treasure of which Fitzsimmons spoke: a Cursed Eye of Paleth.\n\nTake the Cursed Eye of Paleth to the dwarven priest Glorin Steelbrow, in Menethil Harbor.  Ask him how to remove the Eye's curse.", progress = "That drunk Fitzsimmons sent you to me?  Well, you can tell him I don't have any extra ale.  He's going to have to panhandle someone else!", completion = "An Eye of Paleth?  Amazing!  Hmm...there's something wrong with this one.  You found it on one of those shipwrecks?  Well that explains it!  But...I didn't know they had such an Eye on the Third Fleet...\n\nIt's no wonder Fitzsimmons was so spooked.  A Cursed Eye of Paleth is no cause for mirth.", objectives = "Bring the Cursed Eye of Paleth to Glorin Steelbrow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[293] = { id = 293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing the Eye", description = "I can't lift the curse from the Eye of Paleth.  The Eyes were crafted by Human Priests, so you'll have to go to Stormwind to find someone who can help you.  Speak with Archbishop Benedictus.  He is head of the Cathedral of Light in Stormwind.  He can help.\n\nI hope, for your sake.", progress = "What is that orb you have?  It looks...soiled.", completion = "An Eye of Paleth.  But this one has seen much sorrow...it must have been witness to a terrible, terrible tragedy.\n\nLet me cleanse it, for the Eyes were created to shine bright, and their powers can be quite dangerous if tainted like this one.", objectives = "Bring Archbishop Benedictus the Cursed Eye of Paleth. Benedictus is in the Cathedral of Light, in the city of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[294] = { id = 294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ormer's Revenge", description = "The situation is severe, that much is for sure.  When we uncovered these bones it attracted the Raptors.  These filthy beasts killed my brethren and trapped me, Merrin and the poor Prospector up here.\n\nHelp clear the Wetlands of these Raptors, {name}.  Mottled Raptors and Mottled Screechers are just West of the bluff there.  Kill 10 of each, if you can.\n\nThat will be a good start to the vengeance I have planned for them.", progress = "Kill 10 Mottled Raptors and 10 Mottled Screechers, {name}.  My co-workers did not deserve the fate that was brought upon them.  It's time to even the score.", completion = "Killing is a dirty business, but you did your job well, {name}.  If I weren't obligated to stay with the Prospector and Merrin, I'd be down there shedding blood right along side you.", objectives = "Ormer Ironbraid at the Whelgar Excavation Site wants you to kill 10 Mottled Screechers and 10 Mottled Raptors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[295] = { id = 295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ormer's Revenge", description = "Now it's time to really make those dreaded Raptors regret their blood-thirst.  Just down below there are scores of Mottled Scytheclaws and Mottled Razormaws.  Make those rotten creatures pay by slaying 10 of each!", progress = "I want to make those Mottled Scytheclaws and Mottled Razormaws pay for what they did.  Have you killed 10 of each yet?", completion = "You did a bang-up job of clearing out those Raptors, {name}!", objectives = "Ormer Ironbraid wants you to kill 10 Mottled Scytheclaw raptors and 10 Mottled Razormaw raptors then return to him at the Whelgar Excavation Site.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[296] = { id = 296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ormer's Revenge", description = "While you were down there I happened to notice that one of those beasts stood out from the rest.  He was bigger and more menacing.  I bet he's the one who led the others here to cause the disruption to the dig site.\n\nI ask of you now one final task, {name}.  See to it that Sarltooth is brought to justice.  And considering the gravity of his crimes, justice in this case means death!  Bring me one of his talons as proof of his death.", progress = "Is Sarltooth dead? Have you redeemed the memory of the fallen?", completion = "Thank you, {name}.  Your efforts here will not be forgotten.  Many innocent Dwarves died at this site, simply doing their jobs.  The vengeance you delivered to those evil creatures should make them think twice before attacking King Magni's subjects ever again.", objectives = "Ormer Ironbraid at the Whelgar Excavation Site wants you to kill Sarltooth and return to him with one of his talons once the task is fulfilled.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[297] = { id = 297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Idols", description = "Recently, just before the Troggs surfaced within the site, we had uncovered a large number of strange, carved idols.  But we didn't have the chance to study them, for soon after their discovery the Troggs chased us away from the ruins!  And those idols have a strange effect on the Troggs.  It makes them go berserk!\n\nBring me 8 idols - I want to study them, and I want them out of Trogg hands!  You can find the idols on the Troggs infesting the site.", progress = "Do you have those Idols?  We must study them and report our findings to Ironforge!", completion = "You got them!  Nicely done, {name}!\n\nAnd you don't look too worse for wear, even with those berserk Troggs about.  I'm going to keep my eye on you...you show some promise.", objectives = "Bring Magmar Fellhew 8 Carved Stone Idols.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[298] = { id = 298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excavation Progress Report", description = "I need a progress report sent to Thelsamar - a progress report, and a restatement of my request for more blastpowder!  Here's the report.  Take it to Jern Hornhelm.  He's our local contact in Thelsamar.\n\nIt's not a difficult task, but it must be done.", progress = "Oh, a progress report from the site?  Very good!", completion = "Bah!  Ironband's having trouble with the Troggs.  I wonder if he wants that blastpowder to aid his digging, or to aid his efforts against the Trogg beasts...\n\nWell, either way it's powder well spent!\n\nBut what's strange is, I sent him plenty of blastpowder weeks ago.  I wonder where it went...", objectives = "Bring Ironband's Progress Report to Jern Hornhelm in Thelsamar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[299] = { id = 299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncovering the Past", description = "Just before the invasion I uncovered a large tablet called the Goaz Stone.  The translated text breaks off in 4 places.  The text speaks of a \"divine plan\" and a \"doomed prophecy.\"\n\nI fear we are running out of time.  I am too old to go down and brave those beasts.  But you are strong.\n\nScour the excavation site and uncover the 4 missing tablet fragments: Ados, Modr, Golm and Neru.  Search for them in ancient artifacts or where the soil is loose.  Bring them to me so I can begin unlocking the mystery!", progress = "Have you uncovered the four fragments yet, {name}?   Ados, Modr, Golm and Neru...", completion = "Ah the Goaz Stone is complete!  Fine work, {name}.  Fine work indeed.  Now I can continue with the delicate translation of this Titan script.  I can make out new words already!  Hmm. . .it says here, \"Old Gods. . .Chained Beneath the Land.\"  This is the beginning of something epic.", objectives = "Prospector Whelgar wants you to scour the excavation site in search of the 4 missing tablet fragments: Ados, Modr, Golm and Neru.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[301] = { id = 301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Ironforge", description = "We'll need approval to get Ironband more blastpowder. You'll have to take his report to the Explorers' League headquarters in Ironforge.\n\nHere's the report. Give it to Prospector Stormpike, and don't forget to duck after you deliver it. Stormpike is hotheaded, and he won't be happy to hear of Ironband's slow progress at the site.\n\nYou'll find Stormpike in the Assembly of Explorers.", progress = "We Stormpikes don't like being bothered with trivial matters, {class}.  I hope you brought news worthy of my valuable attention.", completion = "Curse that Ironband!  I sent him a load of blastpowder weeks ago, but he's made no mention of it in this report.\n\nSo...where did the blastpowder go?!?", objectives = "Take Ironband's Progress Report to Prospector Stormpike.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[302] = { id = 302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powder to Ironband", description = "If Ironband still needs blastpowder, then by Magni he'll have it!  I sent the approval on ahead with a messenger to Jern Hornhelm in Thelsamar.  He'll prepare the powder and other supplies to take to Ironband.\n\nAnd one more thing: I want you to personally see that the shipment of powder reaches its destination.  The last one didn't, so keep your mind sharp and your eyes open.", completion = "What? Stormpike wants you to personally see the shipment to Ironband?\n\nI... suppose that's fine, the only problem is, I've already sent Huldar with the porters, Miran and Saean. You just missed them, they left just a short while ago.", objectives = "Speak with Jern Hornhelm in Thelsamar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[303] = { id = 303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Iron War", description = "War rages both home and abroad.  While mighty Dwarven soldiers give their lives in far off territories in the name of the Alliance, our own lands fall prey to the evil deeds of the Dark Iron Dwarves.  They laid waste to the Thandol Span.  Dun Modr fell soon after.\n\nWe need you to gather force and push the front back.  If you can kill 15 Dark Iron Dwarves, 5 Tunnelers, 5 Saboteurs and 5 Demolitionists, the reserve might arrive in time to finish the drive.\n\nNow make haste!", progress = "Roggo has been unable to contact the reserve forces.  We need offensive pressure on that Dark Iron encampment, {class}.  Now get back out there and serve your duty to King Magni!", completion = "You upheld your orders well, {class}.  You have proven yourself to be a valiant soldier and loyal servant to King Magni and for that I salute you!  With the pressure you applied to the Dark Iron encampment, we now stand a chance of driving them off our lands for good. . .if only the damned reserve would show. . . .", objectives = "Motley Garmason at Dun Modr wants you to kill 15 Dark Iron Dwarves,  5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs and 5 Dark Iron Demolitionists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[304] = { id = 304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grim Task", description = "Many of my soldiers died in the battle of Dun Modr.  My own brother perished when the West Bridge over the Thandol Span was destroyed.  Aye, the Dark Iron dwarves are a devilish breed.  From what Roggo was able to gather, the leader of this band of thugs in the Wetlands is a warlock named Balgaras the Foul.  He is quite a coward however.  He sends his soldiers to do his bidding but stays elusive, avoiding danger.\n\nIf you can find the spineless scum, slay him and bring me his ear.  I will reward you, {class}.", progress = "Were you able to locate Balgaras the Foul yet, {class}?  He has been evading us for quite some time.", completion = "Balgaras the Foul is finally dead.  While his death will not bring back the many innocent dwarves who died needlessly by his hand, it will help to restore peace of mind to those who survived.  With Balgaras dead, the remaining Dark Iron scum should be easy enough to manage.  Now, we must wipe them out before a new leader is sent to these parts.\n\nYou have done well, {class}.", objectives = "Kill Balgaras the Foul and bring his ear to Longbraid the Grim outside of Dun Modr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[305] = { id = 305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of The Excavation Team", description = "Oh my, you must be the scout Longbraid said he would send!  You cannot imagine how worried I have been.\n\nMy wife, Merrin, has been sending me letters each week for the past month.  She is part of the Whelgar Excavation team.  But it has been nearly two weeks since her last correspondence.  Surely something is wrong!\n\nLongbraid said that he would send a scout to check up on things if we did not hear from the team soon.  I assume that scout is you, {name}.  Find Merrin at the excavation site to the east!", completion = "Oh, thank the heavens you are here!", objectives = "Tarrel Rockweaver wants you to travel to the Excavation Site and contact Merrin Rockweaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[306] = { id = 306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of The Excavation Team", description = "It was horrible!  We were uncovering some rare artifacts and we began to discover these large bones.\n\nBefore we knew what was happening, these Mottled Raptors overwhelmed the dig site.  Many lives were lost.\n\nOrmer here -- so brave -- saved the Prospector and me.  He defended us as we ran for shelter.  Now we are trapped.  And our hard work lies in ruin.\n\nHere, take this note back to my sweet Tarrel.  It will explain the situation to him.", progress = "Were you able to find Merrin?  Did she send word?", completion = "Such horrible news!  At least 3 of them survived.  But when will the killing end?  I long for the day when King Magni's subjects can live without fear.", objectives = "Return to Tarrel Rockweaver with Merrin's note.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[307] = { id = 307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filthy Paws", description = "The Silver Stream Mine to the east ran dry long ago.  It was converted by the Miners' League into a storage depot, but now Kobolds have moved in, putting their filthy paws on good, Dwarven tools!\n\nWe'll root out those vermin soon enough, but the League wants someone to get their gear out of the mine before we warriors tromp in there and break things.  It'll be a tough delve - you might want cohorts at your side.\n\nThe gear is stored in Miners' League Crates throughout the mine.  Good luck.", progress = "Do you have that Miners' Gear, {name}?", completion = "Did you see a lot of Kobolds in there?  I can't wait for the order to clear them out of the mine.  The thought of their grimy hands clawing around our mine makes my stomach rumble!", objectives = "Go to the Silver Stream Mine and collect 4 loads of Miners' Gear.\n\nReturn to Mountaineer Stormpike.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[308] = { id = 308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distracting Jarven", progress = "Hmph!  There  is all this booze down here, but I have strict orders not to touch it.  If only I could get a taste of some of our Thunder Ale...that would sharpen my wits, no lying!", completion = "For me?  You're a true hero, {name}!" }
quests[309] = { id = 309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protecting the Shipment", description = "Ready to go, {name}?\n\nFirst, we need to get this powder to Ironband. It'll be a lot for me to carry, and these parts can get dangerous -- and who knows what else the Dark Irons might have in store for me.\n\nI'll feel a lot better with you coming along.", progress = "Where is my powder, {name}? My need grows more desperate every day.", completion = "Oh, thank the Light the powder is here. But it is troubling news that you bring as well. To think that the Dark Irons have sympathizers able to procure this sort of material for their dastardly plans.\n\nThat's a matter for someone else to consider, some other time. I must put this powder to good use.", objectives = "Ensure Miran and the shipment arrive at the excavation site, then inform Prospector Ironband.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[310] = { id = 310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitter Rivals", description = "I have to admit, those Thunderbrews make some good drinks.  But they need to learn that theirs isn't the only decent brew!  Maybe you can help me teach them that lesson...\n\nHere, take this barrel of Barleybrew Scalder.  Sneak into the basement of the Thunderbrew Distillery in Kharanos and switch it with one of their barrels of Thunder Ale.  Then we'll see how their patrons like my brew over theirs!\n\nAnd if the barrels are guarded, then you might have to distract the guard ...", progress = "The date on this barrel shows that it'll soon be tapped.", completion = "You quickly place Marleth's barrel of Barleybrew Scalder among the Thunderbrew barrels.", objectives = "In the basement of the Thunderbrew Distillery in Kharanos, replace a barrel of Thunder Ale with a Barrel of Barleybrew Scalder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[311] = { id = 311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Marleth", description = "Having inserted a barrel of Marleth's Scalder in the Kharanos Distillery's cellar, you grab a barrel of Thunder Ale as proof of the deed...", progress = "Did you make the switch?", completion = "Not bad, {name}!  Did you have a hard time getting past their guard?\n\nNo matter - many thanks, and if you're ever in need of stout with a kick, don't forget the Barleybrews!", objectives = "Bring the barrel of Thunder Ale to Marleth Barleybrew at the Brewnall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[312] = { id = 312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tundra MacGrann's Stolen Stash", description = "I had a month's worth of dried meats salted and locked away for the cold season.  Kept it locked so the bears wouldn't get it!  But while I was off hunting deer, that beast, Old Icebeard, made off with the meat locker.  He won't be able to smash through that Thorium though.  But I'll starve if I can't get my meats back.\n\nYou seem a bit more stealthy than me.  Perhaps you can retrieve my stash?  I'll never make it in and out of that cave fast enough with this bum leg of mine.", progress = "Were you able to get into my meat locker, {name}?", completion = "What a kind soul you are, {name}!  Thanks to your bravery I won't find myself starving when the cold season flurries blow in.", objectives = "Retrieve Tundra MacGrann's dried meats from the stolen meat locker in Old Icebeard's cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[313] = { id = 313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grizzled Den", description = "Driving a Siege Engine isn't for everyone.  It takes an iron grip and nerves of steel...lucky I have both!  How about you?  How's your mettle?  Want to prove it to me?\n\nWell...I'm looking to make my engine, Trollplow, a little more cozy.  How about you get me a heap of Wendigo Manes from the Grizzled Den, west of Kharanos.  Those manes would make a great rug for Trollplow's inside deck!", progress = "Hey, {name}.  Been to the Grizzled Den yet?  Those Wendigos can be fierce.", completion = "Ah yes, these manes will work great!  You show a lot of grit, {class} - I wager we'll see great things from you.", objectives = "Gather 8 Wendigo Manes and bring them to Pilot Stonegear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[314] = { id = 314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protecting the Herd", description = "We heard the cries in the middle of the night.  Then this morning, sure enough, the herd was missing two rams.  That dastardly beast known as Vagash has been preying on our livelihood.  With most of King Magni's army off in distant lands fighting with the Alliance, there is no one to keep Vagash at bay.\n\nPerhaps you are brave enough to seek out the beast and slay him.  Bring me one of his fangs and I will reward you.  Vagash lurks just above the ranch here, but be warned, he is deadly.", progress = "Vagash still terrorizes the herd!  Please help us by killing the wretched beast.", completion = "Very well done!  Veron will be so happy when he hears the good news.  To kill Vagash is no easy task.  I imagine one day you'll be fighting alongside King Magni's men on the Alliance Front.", objectives = "Rudra Amberstill wants you to slay Vagash and bring his fang to her at the Ram ranch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[315] = { id = 315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Stout", description = "I'm on a quest, a quest to make the perfect stout.  I know I can do it -- brewing's in my blood.  I just need to find the right recipe...\n\nThe Frostmane trolls grow a plant, shimmerweed, high up in the hills to the east.  They use it in their strange, tribal rituals.  We dwarves haven't found much use for it, but it has a unique taste...and I want to experiment with it in my brews!\n\nGet me some shimmerweed from Frostmane seers, or swipe it from the trolls' shimmerweed baskets.", progress = "Do you have that shimmerweed?  I almost have a batch of stout ready to brew, and I want to try throwing the weed in with this mixture.", completion = "Great!  I can't wait to use these in some of my recipes.  There's one in particular I think it'll work great in...", objectives = "Bring 6 Shimmerweeds to Rejold Barleybrew in the Brewnall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[317] = { id = 317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stocking Jetsteam", description = "I'm preparing to start a mission for the Siege Brigade.  It's a long one, and I need to stock Jetsteam with a month's worth of supplies.  So while Steelgrill is working on my tank, can you do some hunting for me?\n\nI'll need some fur for bedding, and boar meat for food.  You can get meat from boars and fur from the bears... you can find them both in the snow fields south of the Grizzled Den.", progress = "Preparations are going well.  How goes your hunting?", completion = "By Magni's beard, you sure did a lot of hunting!!  Thank you, {name}.", objectives = "Gather 4 Chunks of Boar Meat and 2 Thick Bear Furs, and deliver them to Pilot Bellowfiz at Steelgrill's Depot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[318] = { id = 318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evershine", description = "Rejold Barleybrew experiments with his brews.  Some of them taste good, some bad, and some...well, some will lay all but the stoutest dwarf flat.\n\nHe lives at Brewnall Village, west of Kharanos, and one of his drinks, Evershine, is what I want.  It'll help keep me warm while I'm on the cold road.\n\nAnd...the blessed stuff burns so hot I can throw it in Jetsteam's furnace for a burst of power!  That little tactic has gotten me out of more than one tight spot.", completion = "Bellowfiz needs some of my Evershine?  Hm...all right.", objectives = "Get a cask of Evershine from Rejold Barleybrew in Brewnall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[319] = { id = 319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Favor for Evershine", description = "I have a cask of Evershine handy, but...can you do me a favor?  Brewnall village could use a hand against the wild animals that wander the nearby snows.  Sometimes they wander close.\n\nWe're not afraid of these bears and cats and boars - no self respecting dwarf would be - but if you can take care of those animals for us, then we'd have more time for our crafting and brewing.", progress = "Have you taken care of those wild animals?", completion = "Thank you, {name}.  It'll be nice to work our crafts without hearing so many growls and snorts outside the village.", objectives = "Kill 6 Ice Claw Bears, 8 Elder Crag Boars, and 8 Snow Leopards, and then return to Rejold Barleybrew in Brewnall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[320] = { id = 320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Bellowfiz", description = "Here's your cask of Evershine, {name}.  And again, thank you for the hunting earlier.", progress = "Did you get that Evershine?", completion = "Yes, this will do just fine.  I think I'll open a bottle right now and have a taste...", objectives = "Give the cask of Evershine to Pilot Bellowfiz at Steelgrill's Depot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[321] = { id = 321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightforge Iron", description = "The shipwrecks off the shore here are the doomed Third Fleet of Kul'Tiras, burned and sunk by Red Dragons during the last Great War.\n\nThe Fleet hailed from Lordaeron, but one ship, an Elvish Destroyer: Flying Osprey, was with it.  It was shipping a load of Lightforge Iron and joined the Third Fleet for protection.  Ironic that it sunk to the same dragons...\n\nEnough history.  The Flying Osprey is wrecked to the south of Menethil Harbor.  If you find the Lightforge Iron there, bring it to me.", completion = "This chest is waterlogged, and its siding broken.  Many claw marks mar both the inside and outside of the chest...as if Murlocs have searched through it and stolen its treasure.\n\nBut tucked deep within the chest is a single Lightforge Ingot.  Unfortunately, many more will be needed if enough metal to fashion a weapon is to be gained.", objectives = "Search the wreckage of The Flying Osprey in the Wetlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[322] = { id = 322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessed Arm", description = "There is a dwarven weaponsmith in the Dwarven District of Stormwind who can craft with lightforge iron.  His name is Grimand Elmore.\n\nI've packed the iron you found into a crate.  Take it to Grimand and tell him your tale.  I'm sure he'll oblige someone on a quest such as yours, and craft for you a weapon - a weapon to give even Morbent Fel worry!", progress = "How might I ply my craft for you, {class}?", completion = "That is quite a tale you have.  And lightforge iron!  Not for years have I worked with such a metal.  It will be an honor to craft with it again.  And you must return to me later with the story of your battle against the Necromancer.\n\nBut we get ahead of ourselves.  First, your weapon against Morbent Fel...", objectives = "Take the Crate of Lightforge Ingots to Grimand Elmore in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[323] = { id = 323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Your Worth", description = "Morbent Fel is a necromancer, and an ally to the dark riders.  I would pit you against the power of Morbent Fel, but I will not send you against that vile fiend without first knowing your strength.\n\nYou have already proven your bravery to me, but if you truly wish to face the necromancer, then you must now prove your skill against his minions.", progress = "Battle hard, {name}.  And do not despair, for despair is evil's greatest weapon.", completion = "Your skill in combat, {name}, can not be doubted.  Your resolve may yet see us through to the end of Morbent Fel!", objectives = "Kill 15 Skeletal Raiders, 3 Skeletal Healers and 3 Skeletal Warders, and then return to Sven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[324] = { id = 324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Ingots", description = "Having grabbed the single lightforge ingot from the waterlogged chest, it is clear that murlocs have stolen the rest.  Hunt the murloc raiders near the Flying Osprey wreckage for the lost lightforge iron.", progress = "Did you find the lightforge iron you need?", completion = "Ah, you found them!  Now let's get this lightforge iron hammered into something useful, eh?", objectives = "Gather 5 Lightforge Ingots, then return to Glorin Steelbrow in the Wetlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[325] = { id = 325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armed and Ready", description = "Here is the weapon against the fiend of which you spoke.  You're all ready, {name}.  Best of luck to you, and I look forward to your tale of glory!", progress = "Hello, {name}.  You haven't been gone that long, but I see a fire in your eyes I did not see before.", completion = "Ah, this will be proof against the fiend Morbent Fel!  Well done!\n\nYou are ready.  Morbent Fel will fall.", objectives = "Bring Morbent's Bane to Sven in Duskwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[328] = { id = 328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hidden Key", description = "Although no mention of Private Thorsen is found in these records, hidden within the binding of one of Herod's ledger books is a small, brass key.\n\nAnd after further study of his notes, a few references to a \"secure strongbox\" are contained among various papers.  The box is somewhere within the Stockpile - the cavern complex at the back of Kurzen's Compound.\n\nIf this secure strongbox is found, and the small brass key can open it, then perhaps the mystery behind Thorsen's detection will be revealed.", progress = "The strongbox is bound in bronze, very sturdy, and very heavy.", completion = "Opening the strongbox, it's clear that this is where Herod keeps his more valuable coins and items.", objectives = "Use the Small Brass Key to open Bookie Herod's Strongbox.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[329] = { id = 329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spy Revealed!", description = "Among the valuables of the strongbox is a muddy, scribbled note.  Although barely legible, it looks to be an itinerary for Private Thorsen.  It details his patrol routes, who he speaks with and how he spends his time with the rebels.  It's signed with only one letter: -M.\n\nBut whoever wrote this note must have stayed very close to Thorsen.  Whoever wrote this note is the traitor within the rebel camp.", progress = "Did you discover who knew Thorsen's secret?  Is there a traitor among us?", completion = "Thank you, {name}.  This note is the clue we need to root out the traitor!", objectives = "Take the Muddy Note to Lieutenant Doren at the Rebel Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[330] = { id = 330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patrol Schedules", description = "The note you gave me is signed with an \"-M\"...I don't know what that could mean.\n\nBut...the note also says this person shared patrol routes with Thorsen last week.  So whoever shared patrol with Thorsen last week must be the traitor!\n\nGo to Corporal Sethman.  He handles the patrol schedules and can tell you who was with Thorsen.", completion = "Oh, yes I can check that for you.  Let's see...last week it was...\n\n...why, it was Private Merle scheduled with Thorsen.  They had the same patrol times all of last week.", objectives = "Speak with Corporal Sethman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[331] = { id = 331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Doren", description = "Did Lieutenant Doren want you to report back to him with that patrol information?", completion = "It pains me to find out it was Merle who betrayed us.  He has always been a brave soldier, and I had thought his heart was true.  But it is a great relief to have found him out - with a spy like him among us...we would not last long against Colonel Kurzen.", objectives = "Speak with Lieutenant Doren.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[332] = { id = 332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wine Shop Advert", description = "If you talk to anyone about wine, then you know we Gallinas sell the best wine in Stormwind.  And we're not far, still in the Trade District along the city's lovely canals.\n\nHere, take this pamphlet.  Bring it to my sister Suzetta at our shop for a complimentary bottle of our famous pinot noir.  You won't regret it!", progress = "Greetings and welcome, master.  Have you yet tried one of our fine wines?", completion = "Ah, so you've seen Renato?  Well here you are, sir.  A bottle of our special pinot noir.  You'll not find its equal in all of Azeroth!", objectives = "Go to the Gallina Winery, and bring Suzetta Gallina the Wine Ticket for a free bottle of wine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[333] = { id = 333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harlan Needs a Resupply", description = "We've been doing a lot of business lately.  It seems like everyone is buying armor and sturdy clothes.  Almost like they expect a cold, harsh season ahead...\n\nBut those are future worries.  My worry today is that I'm running out of knitted clothing to sell.  I need another load from our supplier.\n\nIf you can take this request to Rema Schneider at the Canal Tailor and Fit Shop, I'd be most grateful.", progress = "You bring word from Mr. Bagley?", completion = "It says here that Harlan's business is booming.  That's good news, but I wonder why people have need of all that armor.  I've heard nothing of open war...is there something the nobles aren't telling us?\n\nWell, thank you for bringing the request.  Here's your payment, and I'll see to it that Harlan gets his supplies.", objectives = "Go to the Canal Tailor Shop and bring Rema Schneider the Cloth Request from Harlan Bagley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[334] = { id = 334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Package for Thurman", description = "My son Thurman is an apprentice at the Larson Clothiers, in the Mage's Quarter.  He was in a hurry today and forgot his shears and needles.  I know a great {class} like you must have important tasks at hand, but without his tools Thurman can't do his apprentice work!\n\nPlease, {name}.  Can you take my son's sewing kit to him?  Larson Clothiers is one of two clothing shops in the Mage's Quarter - it's the one deeper in, near the Mage's Tower.", progress = "Are you here to buy clothes?", completion = "Oh, blast!  I thought forgetting my kit would free me from work.  Now I guess I'll have to help the Larsons with their sewing...\n\nOh, well.  Fun will come later I guess.", objectives = "Go to the Larson Clothiers in the Stormwind Mage Quarter, and give Thurman Schneider his Sewing Kit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[335] = { id = 335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Noble Brew", description = "Lord Wishock is causing quite a stir amongst the House of Nobles.  He was made aware of our little \"establishment\" down here and is lobbying for a full investigation.  I have a plan to keep Wishock \"preoccupied,\" but I'll need your help. \n\nThere is a flower growing in the Garden of Stalvan on the outskirts of Darkshire.  This small white flower is known as the Tear of Tilloa.  I will also need a Musquash Root, found only at the very base of the falls far beneath the Stonewrought Dam in the Wetlands.", progress = "Wishock will soon garner enough support to cause us much grief.  Were you able to obtain the Tear of Tilloa or Musquash Root yet?", completion = "Most excellent! These are fine samples indeed!", objectives = "Zardeth the Black Claw wants you to bring him a Tear of Tilloa from Darkshire and a Musquash Root from the Wetlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[336] = { id = 336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Noble Brew", description = "Lord Wishock, like all men, has his weaknesses.  His happens to be a fondness for liquor.  The hypocrisy is astounding.  The trite fool spends his days trying to shut down our little \"tavern\" while his nights are spent upstairs, running up a bill he never pays.  Well, let's see how Wishock likes this special brew I have prepared for him:  Black Claw stout.  It's got quite a kick, {name}.\n\nTake it to him and see how he likes it.  Most likely the old fool is milling about the Hall of Petitioners.", progress = "Can you not see that I am busy?  My words must be heard!  I am very important to the future of this Kingdom!\n\nOh... what have you there?  Why it looks like a refreshing drink...", completion = "Ah, thank you for bringing me this fine looking stout, servant.  Here's a copper for you.  Now, out of sight with you and let me enjoy my drink!", objectives = "Take the Black Claw Stout to Lord Wishock in the Hall of Petitioners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[337] = { id = 337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Old History Book", description = "Although the cover of this book is marred by scratches and caked with mud, the words \"The History of Stormwind\" can still be read along its spine.  Upon opening the book, the seal of the Stormwind Library is clearly stamped on the book's first page.\n\nIt looks like someone checked out this book, and never returned it...", progress = "Ooh!  What's that old book you have there?  Can I see it??", completion = "Oh my!  This book hasn't rested on these shelves since before the rebuilding of Stormwind, years ago.  It will have to be restored of course, it's in bad shape, but I would be honored to place it within our rare books collection.\n\nThank you, sir.  Please accept this as payment for returning the book!", objectives = "Return the book: The History of Stormwind, to the Stormwind Library.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[338] = { id = 338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Green Hills of Stranglethorn", description = "Master Nesingwary will be so upset if he finds out!\n\nHe trusted me to proofread the manuscript of his novel, The Green Hills of Stranglethorn.  Everything was going well, but a large gust of wind blew through the camp and scattered the pages everywhere!\n\nI was able to gather most of the pages but many are still strewn about the jungle.  Collect the pages to complete each of the four chapters.\n\nI will help you organize them.  Return the chapters to me once you have all four.", progress = "Have you assembled the chapters yet, {name}?", completion = "You've certainly saved me a heap of trouble, {name}!  I can't thank you enough.  It shouldn't be long now until we see Master Nesingwary's book in libraries throughout the world!", objectives = "Collect the missing pages from The Green Hills of Stranglethorn manuscript. Once all four chapters are complete, return them to Barnil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[339] = { id = 339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chapter I", description = "Chapter I was quite riveting!  Master Nesingwary sets the backdrop for the story and makes mention of his hunting companions, including me! \n\nBut that's besides the point.  Let me see which pages are still missing.  It seems pages 1, 4, 6 and 8 are still out there somewhere in the jungle!", progress = "I don't suppose you were able to track down pages 1, 4, 6 and 8?  Those four are all we need to piece Chapter I back together.", completion = "At last!  Chapter I is complete!", objectives = "Bring pages 1, 4, 6, and 8 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter I.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[340] = { id = 340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chapter II", description = "Chapter II was chock full of exciting tales of panther and tiger hunting.  I could just kick myself for letting the pages blow away! \n\n It seems I was able to recover all of the pages with the exception of pages 10, 11, 14, and 16.", progress = "We still need pages 10, 11, 14 and 16 to complete Chapter II, {name}.", completion = "Chapter II is finally complete!  Well done!", objectives = "Bring pages 10, 11, 14 and 16 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter II.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[341] = { id = 341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chapter III", description = "Chapter III was my favorite.  It tells of Sir Erlgadin and Lady Rouack's first kill with a dwarven rifle.  And the end of Chapter III, why, such a cliffhanger!  \n\nLooks to me as though we still need pages 18, 20, 21 and 24 to finish the chapter.  Those pages are out there somewhere. . .", progress = "Any luck with pages 18, 20, 21 or 24?  Those are the only ones we need to piece together Chapter III.", completion = "Phew!  Good work, {name}.  Chapter III is now back together in one piece!", objectives = "Bring pages 18, 20, 21and 24 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter III.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[342] = { id = 342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chapter IV", description = "Ah Chapter IV; the big finale!  And what an ending it was! \n\nWe are only missing three pages for this chapter.  We need pages 25, 26 and 27 to put Chapter IV back together.", progress = "We just need three pages to finish off Chapter IV, {name}.  Do you have pages 25, 26 or 27 yet?", completion = "Superb!  We now have Chapter IV ready to go!", objectives = "Bring pages 25, 26, and 27 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter IV.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[343] = { id = 343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speaking of Fortitude", description = "I'm giving a speech on the Fortitude of the Spirit, and I'd like to recite passages from a particular book on metallurgy - \"The Stresses of Iron.\"  A copy of this book should be in the Royal Library, within Stormwind Keep.  Can you retrieve it for me?  If so, then may the blessings of the Light be with you!\n\nThe Royal Library is very large, but the head librarian, Milton Sheaf, knows each shelf like it was his own son.  Speak to him, he'll retrieve the book for you.", completion = "Metallurgy?  Ah yes, we have many books on the subject, and are happy to aid Brother Kristoff with his speech!  Now...which particular book was it the good brother needed?", objectives = "Go to the Royal Library in Stormwind Keep and speak with Milton Sheaf. He can find for you the book on metallurgy that Brother Kristoff needs for his speech.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[344] = { id = 344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brother Paxton", description = "The Stresses of Iron?  Yes, I know the book.  Quite a good one, written by the Dwarven miner Margulf Blaggon a few decades ago.  He spent most his time deep in the mountains of Khaz Modan, digging ore.  Smart fellow!\n\nBut where was I?  Oh yes, the Stresses of Iron!  I'm afraid the book was moved to the Northshire Abbey.  The caretaker of the Abbey's library, Brother Paxton, wanted to make a copy of the book for his own shelves.\n\nBut that was months ago.  I wonder why it's taking him so long...", completion = "Mr. Sheaf is wondering where his book is?  Well this is a tad embarrassing.  I have the book, but I'm still making my copy and I'm not quite ready to give the original up!", objectives = "Speak with Brother Paxton in the Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[345] = { id = 345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ink Supplies", description = "I've been meaning to finish my copy of The Stresses of Iron, but...\n\nWell you see, I make my own ink for books I copy.  It's my own recipe; it doesn't run or smear, and it dries very quickly  Unfortunately, it dries too quickly!  My last batch dried up before I could finish the copying job, and I haven't had the chance to make more ink!\n\nTo make more I need Rethban Iron Ore from the Redridge Mountains.  Foreman Oslow in Lakeshire is my usual supplier.", completion = "You need what??  Maybe you haven't noticed, but we're busy fortifying Lakeshire's defenses and repairing damage from recent orc attacks.  If you need Rethban Iron Ore, you'll have to get it yourself!", objectives = "Speak with Foreman Oslow in Lakeshire and ask him for Rethban Iron Ore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[346] = { id = 346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Kristoff", description = "Now that I've finished copying the book, here's the original Stresses of Iron.  Thank you for your patience, and if you see Milton please tell him I'm sorry for the long delay.", progress = "Were you able to find the book?", completion = "That's the one!  Thank you, {name}.  May the Light shine brightly upon both your body and spirit!", objectives = "Return to Brother Kristoff in the Cathedral Square. Give him the book The Stresses of Iron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[347] = { id = 347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rethban Ore", description = "Rethban Ore is named after the man who first found it, Bart Rethban.  When smelted it's not as strong as iron, but its ore has a dark, flat color that some scribes use in their dyes.  It can be found in the Rethban Caverns, north of here.\n\nWe usually have some in stock, but we're too busy preparing for Orc attacks to gather any.  And besides...Redridge Gnolls are now living in the Rethban Caverns and their Drudgers are gathering the ore themselves.\n\nSo if you need some, you'll have to get it yourself.", progress = "Do you have the Rethban Ore?", completion = "Oh, splendid!  I can use this ore to make my dye, and then can finish copying The Stresses of Iron.\n\nThank you, {name}!", objectives = "Gather 5 loads of Rethban Ore and bring it to Brother Paxton in the Northshire Library.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[348] = { id = 348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranglethorn Fever", description = "Sick...so...very s-s-sick....\n\n...have contracted Stranglethorn Fever...deadly v-v-virus...\n\n...only cure...is...is...to eat the heart of M-m-m-m-mokk the Savage...elusive white beast...\n\n...Witch doctor Unbagwa...only one who can s-s-summon....\n\n...seek Unbagwa in hidden cave on southern cape...\n\n...hurry...dying...dying....", progress = "....mother?\n\n...so cold...\n\n...heading into the Twisting Nether...h-h-h-hold me mother....", completion = "...feel strength returning....\n\nWhere might be?  Booty Bay?  Oh my!  I had the strangest dream...\n\n...the weakness has not completely left me....", objectives = "Seek out Witch Doctor Unbagwa and have him summon Mokk the Savage. Bring the Heart of Mokk to Fin Fizracket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[349] = { id = 349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranglethorn Fever", progress = "Witch Doctor Unbagwa know what Mokk the Savage like.  Yes, yes!\n\nMe speak with spirits and make he come, I do.\n\nBut other Gorilla-beast like spirit talkin' too.  You protect Witch Doctor Unbagwa and I make he come to you.\n\nWitch Doctor Unbagwa want something first.  You bring 10 Gorilla Fangs and me start spirit talking!", completion = "Witch Doctor Unbagwa like Gorilla Fangs!  For you I talk to spirits.  Make Mokk the Savage come.\n\nYou protect Witch Doctor Unbagwa from other Gorilla-beast though or no Mokk for you!" }
quests[350] = { id = 350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Look to an Old Friend", description = "That Marzon would be contacting a member of the Defias and have ties to Lescovar...\n\nHaving killed VanCleef and Thredd, it would be hard to see Lescovar brought to proper justice, as your evidence is nothing without their testimonies. That is not even considering the fact that Lescovar is a noble and well connected. It effectively makes him above the law.\n\nYou'll need other help. I loathe to do so, but there is someone I know that will aid us. You'll find Trias in the Trade District of the city.", completion = "You're kidding? Shaw wants my help again? Of all the nerve...\n\nThe Defias Brotherhood, you say? Well, you're certainly the bearer of wonderful news, aren't you? Next you're going to tell me that Deathwing is still alive and attacking the city.\n\nAll right, tell me everything from the beginning. And don't leave out something you think might not be important. I need to know it all.", objectives = "Speak to Elling Trias in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[351] = { id = 351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find OOX-17/TN!", description = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"The name's Oglethorpe, and my homing robot has gone missing!  I will reward you for its recovery!  Please take this beacon to the robot.  Excellent, I now have computed the coordinates for you!  It crashed near the Gaping Chasm in Tanaris!\"", progress = "You appear to have uncovered the wreckage of... a robotic chicken?  The voice from within the egg crackles to life again:\n\n\"Yes, excellent work!  This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs.  Go ahead and place the beacon inside the rover.  The beacon will take care of the rest!\"", completion = "You place the egg... distress beacon... inside the chicken... homing robot.\n\nHums and whirs are heard from inside the robot as it struggles to stand up.  After the robot comes to life, Oglethorpe's voice is heard once more, but now from inside the robot:\n\n\"OOX-17/TN is working at least, but it needs major repairs!  It is much too heavy for you to carry it... but I think I have an idea.  Are you up for watching over it some more?\"", objectives = "Bring the distress beacon to Oglethorpe's homing robot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[353] = { id = 353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormpike's Delivery", description = "The Stormpikes are a respected dwarven clan, and are well known for their fine and discerning tastes.  So it's no wonder that Gringer Stormpike, a Mountaineer of Ironforge, commissioned me to craft him a weapon.\n\nThe weapon is finished, but... Mountaineer Stormpike is far away, in distant Loch Modan.  If you plan on traveling to the north, can you deliver this package to him?\n\nMy last message from Mountaineer Stormpike said he's stationed at the northern guard tower in Loch Modan.", progress = "You come all the way from Stormwind?  I hear it's getting dicey down there in the {race} lands, with brigands and orcs running about.  A perfect place for a {class} to prove their worth!", completion = "Aha!  So Grimand finally finished my axe!  I can't wait to try it against some troggs and kobolds!\n\nMany thanks, {name}.  It was a long distance to travel for this delivery.   Here are some coins for your efforts.", objectives = "Deliver the Package for Stormpike to Mountaineer Stormpike in Loch Modan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[354] = { id = 354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deaths in the Family", description = "The Agamand family was the most prosperous family in Tirisfal Glades.  I used to work their mills...before the Plague.\n\nWhen the Scourge first came, the Agamands fortified their home and convinced those in their employ to remain and help them defend.  We were fools, but at least we were loyal fools.\n\nThe Agamands, in their pride, doomed us to undeath.  And now they are minions of the Scourge!\n\nServe the Forsaken by defeating the Agamands who fell to the Plague.  Serve me by bringing me their remains.", progress = "Do you have the remains of the Agamands?  Are those cursed beasts finally destroyed?", completion = "Revenge has a sweet taste, don't you think?  When you destroyed the Agamands, did you catch any hint of free will within them?  I hope so.  I hope they knew fear before they were smashed into oblivion.\n\nIt is a foolish hope, I know.  But it is a hope I foster nonetheless.", objectives = "Bring Gregor's Remains, Nissa's Remains and Thurman's Remains to Coleman Farthing in Brill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[355] = { id = 355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Sevren", description = "You have given me the remains of the Agamands, and satisfied my desire for revenge.  But the Agamand Mills hold a threat to all the Forsaken, not just to me.\n\nI have spoken to Magistrate Sevren of your exploits against the Agamands, and he wishes to speak with you.", completion = "Coleman speaks well of you, {name}, telling of your successful forays into the Agamand Mills.\n\nThe Forsaken have need of your talents once again...", objectives = "Speak with Magistrate Sevren in Brill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[356] = { id = 356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rear Guard Patrol", description = "The defenders on The Bulwark protecting Tirisfal from the Plaguelands are on constant alert.  But sometimes Scourge will slip past them.\n\nOur success at the Bulwark depends on a one-front battle - we cannot allow an attack from the rear, nor can we allow our defenders' supply line to be cut.\n\nAssist the Bulwark.  Patrol east and slay any Scourge you find.  Spend particular effort at the Balnir Farmstead to the east.  It has become a haven for interloping Scourge.", progress = "Do you have a report of your patrol?", completion = "Very good.  Your efforts do much to keep the Scourge at bay.  A commendation will be sent to my superior, Executor Zygand.", objectives = "Kill 8 Bleeding Horrors and 8 Wandering Spirits, then report back to Linnea at her camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[357] = { id = 357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lich's Identity", description = "There is a lich who dwells on the island in Brightwater Lake to the north.  Although he is a free-willed Forsaken, he believes all other Undead are Scourge slaves and has his minions attack anyone who approaches him.\n\nBut because he is Forsaken, the Queen will want him.  And if he is skilled in Necromancy, then his knowledge would be...quite useful to us.\n\nTo discover his identity and his talents, I must see his spellbook.  Steal into his camp and acquire it, then return to me.", progress = "{name}, have you acquired the book?", completion = "Very good, {name}.  I will study this book and determine the identity of that lich.  You have served your Queen well.\n\n\n\nAstonishing!  The book you retrieved belongs to no one other than Gunther Arcanus!\n\nGunther was a skilled Necromancer in life; he and I were friends and comrades-in-arms, before the Plague.  And judging from his book he has grown even more powerful in death.\n\nHis skills would be a great boon to us.", objectives = "Bring the Lich's Spellbook to Bethor Iceshard in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[358] = { id = 358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Graverobbers", description = "The Mass Graves, southwest of Garren's Haunt to the north, were made to accommodate the...impressive...number of deaths Tirisfal suffered when the Plague first came.  \n\nThe bodies in these graves have so far been spared an undeath, but the Scourge now send Rot Hide Gnolls to gather the corpses and use them to bolster their armies.  This cannot be allowed!\n\nYour task is twofold: slay the Rot Hides at the Mass Grave and Garren's Haunt, and gather from them the Embalming Ichor that gives them life.", progress = "Is your task complete?  Have you destroyed those dog-things and drained them of their ichor?", completion = "Expertly done, {name}.  The Scourge are mistaken if they think they can use those corpses against us, and the fluid you gathered from the Rot Hide slaves will be studied by our Apothecaries.  It may have secrets we can use against them.\n\nAs I said, well done.  But our struggle continues, and the conflict will surely offer you more chances to prove your worth to the Forsaken.", objectives = "Kill Rot Hide Graverobbers and Rot Hide Mongrels. \n\nBring 8 Embalming Ichors to Magistrate Sevren in Brill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[359] = { id = 359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forsaken Duties", description = "I need a fresh report from our Deathguard waystation to the east.\n\nI must know if more Scourge forces have slipped past The Bulwark and into Tirisfal.  Our vigilance on the border to the Plaguelands must be maintained - we can't let the Scourge get a stronger foothold here!\n\nTravel south along the road, then east at the fork to the waystation.  Speak with Deathguard Linnea.  She has the information I need.", completion = "Magistrate Sevren wants a report?  Very well: the defenders at The Bulwark are holding the majority of the Scourge at bay, but some do slip through on occasion.\n\nWe have seen sporadic Scourge activity east of this station, with a concentration around the Balnir Farmstead.", objectives = "Speak with Deathguard Linnea.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[360] = { id = 360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Magistrate", description = "Now return to Magistrate Sevren with the information I gave you.  He'll want it as soon as possible, so be swift.\n\nAnd if you see any Scourge on your way back, take them down - we can't let them wander our lands unchallenged.", completion = "It is troubling to hear of the Scourge slipping past the Bulwark.  The Lich King and his minions are ceaseless in their assaults.\n\nBut we will not give in.  He will not take us again!", objectives = "Return to Magistrate Sevren in Brill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[361] = { id = 361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Letter Undelivered", description = "This is a letter written by Thurman, the eldest son of Gregor Agamand.  It is addressed to an Yvette Farthing, though it does not appear to have reached her...", progress = "Yes?", completion = "Oh...my poor Thurman!  I begged him to leave Agamand Mills with me and my father, but his family loyalty was too strong!  And I knew it!  I just knew it that Brand meant him harm!!  Oh, curse this Plague, and the Scourge!\n\n<Yvette's face then smoothes and grows cold.>\n\nBut regrets are for the weak.  As a Forsaken, I have new goals and love is not one of them.  I would thank you for delivering this letter, for I had wondered what happened to my past love.\n\nBut that life is over.  Forever.", objectives = "Find Yvette Farthing, and deliver to her the letter from Thurman Agamand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[362] = { id = 362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Haunted Mills", description = "Devlin Agamand was the younger of two sons in the Agamand family, and in life the two could not be more different.  Thurman was tall and gentle while his younger brother was weak and sharp tongued.\n\nWhen Agamand Mills fell to the Plague, I was not surprised to hear that Devlin was quick to succumb.  His mad chattering can still be heard near the road leading to the Agamand Mills.\n\nI'm collecting the remains of the Agamands, and I want poor Devlin.  Find him, destroy him, and bring me his bones.", progress = "Did you find Devlin?", completion = "Thank you.  Devlin's bones will rest nicely on my mantle.\n\nIf my cold heart can find warmth, it is in knowing that the Agamands are destroyed.  They failed me and my family when the Plague came - now I swear I will smash their remains under my heel!", objectives = "Slay Devlin Agamand, and bring Devlin's Remains to Coleman Farthing in Brill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[363] = { id = 363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rude Awakening", description = "About time you woke up. We were ready to toss you into the fire with the others, but it looks like you made it.\n\nI am Mordo, the caretaker of the crypt of Deathknell. And you are the Lich King's slave no more.\n\nSpeak with Shadow Priest Sarvis in the chapel at the base of the hill, he will tell you more of what you must know.", completion = "Another of the walking dead, hm? Must have been quite a shock, waking up in the crypt with only the cold and Mordo to greet you...\n\nI see the confusion on your face. Let me try to explain our... situation... to you.\n\nWe have been freed from the control of the Lich King by our new leader, Lady Sylvanas. The Dark Lady guides us in our war against the hated Scourge and the holdouts of humanity who dog our every step.", objectives = "Speak with Shadow Priest Sarvis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[364] = { id = 364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mindless Ones", description = "We Forsaken are at war with the Lich King's army of the Scourge: necromantically raised armies of the undead, foul beasts of the north, and tormented spectres.\n\nThe northern part of the village has become overrun with the Mindless Ones, and they must be destroyed. Destroy them, show them no mercy, our former brothers and sisters as they might be. The Fallen are nothing but The Lich King's slaves.", progress = "You will not go far in this new life if you are unable to kill even the weakest of zombies, {name}. Do not return until you have success to report.", completion = "It is unfortunate that the Scourge cannot be brought into the fold, their large numbers would be useful in the battles ahead.\n\nBut they will not join us, so we have no choice but to destroy them.", objectives = "Shadow Priest Sarvis wants you to kill 8 Mindless Zombies and 8 Wretched Zombies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[365] = { id = 365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fields of Grief", description = "What have we here?  You look like a fledgling {class}.  If you hope to prove yourself to The Dark Lady, you need to learn the ways of The Forsaken.\n\nTo the west you'll find a farm.  Humans infest the land like mold on a rotting corpse.  And worse yet, the Scarlet Crusade patrols nearby from their tower.  Teach those scum a lesson and steal 10 of their precious pumpkins.\n\nOnce you have 10, take them to Apothecary Johaan in Brill.", progress = "Deathguard Simmer sent word that you were going to provide me with some much needed reagents.  Were you able to gather 10 pumpkins yet, {name}?", completion = "You have performed your bidding well, young {class}.  You are proving yourself to be quite an asset to The Dark Lady's army.", objectives = "Steal 10 pumpkins from the farm to the west, just north of Deathknell and take them to Apothecary Johaan in Brill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[366] = { id = 366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return the Book", description = "Long ago Gunther and I, along with the now Scourge Necromancer Thule Ravenclaw, were friends and students within the Kirin Tor - a society of mages in Dalaran.\n\nGunther and I both fell to the Plague, but I thought he either remained dead, or was raised into the ranks of the Lich King.  It is good to know he is free.\n\nWe must have him.  I have placed a spell on his book that, when he sees it, will show him that I too am free of the Lich King.  After knowing this, it is my hope that he will join us.", progress = "Your masters are fools to send you here, for I will never again be a Scourge slave!", completion = "My book?!?  So you were the thief who stole it!\n\nBut...what is this new enchantment upon it...Bethor?  He is in  Lordaeron?\n\nIf he still exists, then perhaps he too escaped from the Lich King's grasp...", objectives = "Return Gunther's Spellbook to him, on the island of Gunther's Retreat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[367] = { id = 367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Plague", description = "Lady Sylvanas has called upon the Royal Apothecary Society. The Dark Lady believes our knowledge coupled with the newfound magic will provide the key to Arthas's demise.  She has challenged us to concoct a new plague, a plague deadlier than any ailment on Azeroth. This new disease will bring Arthas's Scourge Army to ruin.\n\nMy studies show that the blood of beasts might prove to be the key. Bring to me 5 vials of darkhound blood so I can test my theory.", progress = "Have you collected 5 vials of darkhound blood yet, {name}? Time is fleeting!", completion = "You have done well, {name} and I thank you for your efforts.", objectives = "Apothecary Johaan in the town of Brill wants you to collect 5 Vials of Darkhound Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[368] = { id = 368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Plague", description = "While you were collecting samples for me, my experiments led me to realize that more reagents will be required for this new disease to spread properly. Poisoning some hapless victim is child's play. Plaguing an entire world proves to be a bit more complicated.\n\nI will need 5 Vile Fin Scales from Murlocs in the vicinity.  You will find the creatures along the coast to the north or to the west.", progress = "{name}, were you able to obtain 5 Vile Fin Scales from the Murlocs?", completion = "The scales are perfect, {name}. Exactly what I needed for this concoction.", objectives = "Apothecary Johaan of the town of Brill needs 5 Vile Fin Scales from Murlocs in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[369] = { id = 369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Plague", description = "While you were out gathering, I uncovered some old text in one of my tomes that indicates that an ancient plague wiped out thousands of innocent victims.  Later it was discovered that the deadly agent in the plague was preserved through the venom of Night Web Spiders.\n\nBring me some venom from a Vicious Night Web Spider to complete this experiment.  I want to see if the contagious element from the venom will work with my new concoction.  Rumor has it the spiders can be found in Eastern Tirisfal Glades.", progress = "Do you have some venom from a Vicious Night Web Spider yet, {name}?  It's the final component I need in order to test my experiment.", completion = "Ah, this venom will do perfectly, {name}.  Everything else has been added to my concoction and boiled down.  Finally, I am ready to try this new deadly agent!", objectives = "Apothecary Johaan in the town of Brill wants you to bring him 4 samples of venom from a Vicious Night Web Spider.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[370] = { id = 370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At War With The Scarlet Crusade", description = "The strategic documents from Executor Arren contain all the details we need to wipe the human infestation from the lands.  According to the information, The Scarlet Crusade has assigned Captain Perrine and a brigade to the ruined tower southwest of Brill.\n\nKill Perrine along with 3 Zealots and 3 Missionaries and report back to me.", progress = "Young {class}, you shouldn't be wasting your time here in Brill when your people need you fighting for their cause.  Now, take up arms and travel to the southwest, to the ruined tower, and slay Captain Perrine along with 3 Scarlet Zealots and 3 Scarlet Missionaries.  We shall herd the Scarlet Crusade like cattle to their demise.", completion = "Captain Perrine's death will undoubtedly please The Dark Lady.  You have performed your duty well, {class}.", objectives = "Executor Zygand in Brill wants you to kill Captain Perrine, 3 Scarlet Zealots and 3 Scarlet Missionaries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[371] = { id = 371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At War With The Scarlet Crusade", description = "We are still at war and the Scarlet Crusade grows in strength.  The report Executor Arren sent me indicates Scarlet Crusaders have been raiding from the ruined tower in southeastern Tirisfal near the Balnir Farmstead under the command of Captain Vachon.\n\nKill Vachon along with 5 Scarlet Friars. It should prove to be a devastating blow to the Crusade!", progress = "I see you have returned but your task is not complete.  Perhaps you are at ease with the mere humans interfering with The Dark Lady's plan?  Or perhaps you can heed the call of duty and slay Captain Vachon and his band of Scarlet Friars!", completion = "Captain Vachon's death will slow down the Scarlet Crusade's advancement in Tirisfal quite a bit.  But other threats loom.", objectives = "Executor Zygand in Brill has commissioned you to slay Captain Vachon and 5 Scarlet Friars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[372] = { id = 372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At War With The Scarlet Crusade", description = "Scarlet Crusaders have been raiding from the ruined tower in northern Tirisfal, past Faol's Rest.  According to the information we have, a ruthless commander named Captain Melrache is in charge of this evil crew.\n\nI am entrusting you now with a special and dangerous mission.  Slay Melrache and his two bodyguards, in the name of The Dark Lady.", progress = "You have not yet performed your duty, {class}.  We cannot expect to carry out The Dark Lady's plan with the Scarlet Crusade pestering our soldiers.  Bring about their deaths and perform your duty to Sylvanas!", completion = "You have done extremely well, {class}.  With ruthless fighters like you conquering in the name of The Forsaken our race is one step closer to defeating Arthas once and for all.  I have a good feeling about you, comrade.", objectives = "Executor Zygand in the town of Brill wants you to assassinate Captain Melrache and his two bodyguards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[373] = { id = 373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unsent Letter", description = "Searching Edwin VanCleef's person, you discover, among other things, an unsent letter. It is addressed to Baros Alexston, the City Architect of Stormwind, City Hall, Cathedral Square.\n\nIt appears to be recently written and sealed.", progress = "Yes? Is there something I can help you with?", completion = "Edwin VanCleef, you say? I would as much expect a letter from my dead grandmother... So you've killed him then? Pardon me in saying, but I'm somewhat surprised. He was a peerless fighter in his younger years. Let's see what he finds the need to write to me about after so many years.\n\n<Baros peruses the letter.>\n\nEdwin... I see the years haven't changed you a bit, an idealist as ever, and a romantic. He doesn't care who he hurts, {name}. Revenge has consumed him. But then, I'm not sure I can blame him.", objectives = "Deliver the Letter to the City Architect to Baros Alexston in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[374] = { id = 374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise", description = "Executor Zygand tells me you've been out killing Scarlet Crusaders. Tirisfal Glades is crawling with them.\n\nVarimathras, lieutenant to The Dark Lady, is seeing to it personally that the scum of Azeroth, the Human race, gets wiped into oblivion. Here in Tirisfal Glades we face a particularly annoying breed of humans: The Scarlet Crusade.\n\nVenture forth and wage an offensive on the Scarlet Crusade, {class}. Bring me back 10 Scarlet Insignia Rings as proof of your loyalty to Varimathras and The Dark Lady.", progress = "Have you collected 10 Scarlet Insignia Rings yet, {class}?", completion = "Varimathras would be proud.  You serve your leaders well, {class}.", objectives = "Bring 10 Scarlet Insignia Rings to Deathguard Burgess in Brill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[375] = { id = 375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chill of Death", description = "It's so cold, now.  The Plague of Undeath crawls through my veins like an icy serpent.  The Mindless State will be upon me soon.  But no doomed destiny will prevent me from serving our Dark Lady.  When the call arose I sewed body bags for the fallen soldiers of Sylvanas's mighty army.\n\nNow my hands shake from the chill.  If you would bring me five Duskbat Pelts and some Coarse Thread I could sew myself a blanket.  Help me, {name}, so that I can continue to serve the cause.", progress = "Do you have five Duskbat Pelts and some Coarse Thread yet, {name}?", completion = "I appreciate your efforts, {name}.  May Sylvanas recognize your bravery one day. . . .", objectives = "Bring five Duskbat Pelts and some Coarse Thread to Gretchen Dedmar in Brill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[376] = { id = 376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Damned", description = "My duties include tending to our wounded warriors, tailoring armor and clothes, and assisting Shadow Priest Sarvis with whatever else he might need.\n\nFrom the look of it, you'll be enlisted in his service also... hunting the Mindless Ones, if I know his mind. Well, if you'd like to stay in one piece--and I've no doubt you do--perhaps I can help. I'm running out of paws and wings, and if you bring me some, I'll find some armor for you. You'll find a good number of wolves and bats to the south.", progress = "Do try your best to keep yourself unharmed until I get you some armor.", completion = "Thank you, {name}. This armor should help you out.\n\nHopefully, it should do you more good than the last one to wear it...", objectives = "Novice Elreth requires 6 Scavenger Paws and 6 Duskbat Wings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[377] = { id = 377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crime and Punishment", description = "As if the neglect for the residents of Duskwood was not bad enough, now the House of Nobles spits in the eye of the Darkshire Council with their decision to imprison Dextren Ward in Stormwind rather than behead the villain as per Lord Ebonlocke's sentence.\n\nWard was caught selling bodies from the cemetery to Morbent Fel, a crime punishable by death.  Yet Stormwind claims Ward as their prisoner.\n\nAssassinate Ward in The Stormwind Stockade - bring me his hand - and I shall reward you.", progress = "So long as a molester of the dead like Dextren Ward is permitted to live, justice stands betrayed.  Return to me once Lord Ebonlocke's sentence of death is carried out on that defiler, Ward.  We shall give the families of the dead the closure they deserve and better yet, we will send a clear message to the House of Nobles in Stormwind.", completion = "So Dextren Ward finally paid for his crimes against humanity?  Good riddance to the scum I say.  And cheers to you, my friend!  Not only have you given the families of the dead the peace of mind they deserve, you sent a poignant message to those corrupt bureaucrats in the House of Nobles.  Stormwind must rise to the needs of the people of Duskwood or we will break free from their tyranny.", objectives = "Councilman Millstipe of Darkshire wants you to bring him the hand of Dextren Ward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[378] = { id = 378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fury Runs Deep", description = "You have proven your loyalty to King Magni, {class}.  And your hatred for the Dark Iron scum is as great as my own.\n\nThere is a task I wish to complete myself but I am bound by honor to stay with Longbraid.  But Roggo has gathered intelligence that proves Kam Deepfury was a conspirator in the attack on the Thandol Span.  It was by Deepfury's planning that Longbraid lost his kin.\n\nDeepfury is being held for political reasons in the Stormwind Stockade.  I want him dead, {name}.  For Longbraid!  Bring me his head!", progress = "I won't let foolish Human bureaucracy interfere with Dwarven matters, {name}.  Kam Deepfury is a proven conspirator in the Thandol Span attack.  King Magni's good people lost their lives because of Deepfury's deceit.  The Humans might be content to let Deepfury rot in The Stockade but I will not sleep soundly at night until Deepfury is slain.", completion = "So Kam Deepfury finally got to feel what it is like to be on the receiving end of Death?  Good.  Serves the cowardly Dark Iron scum right.  You have done well, {class}.  The victims of the Thandol Span attack were but mere victims in a world torn with war and unrest.  Their families will have the peace of knowing Deepfury got the punishment he deserved.  Longbraid's brother's death has been avenged.", objectives = "Motley Garmason wants Kam Deepfury's head brought to him at Dun Modr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[379] = { id = 379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slake That Thirst", description = "You want a power source.  I can help you with that.  Know what I want?  I want something to drink!  Bring me five Wastewander Water Pouches, and I'll give you the 4711-FTZ.\n\nNow... guess where you can find Wastewander Water Pouches!  Why don't you walk up to one of the Wastewander nomads to the east of here and ask them for one.  Let me know how that works out for you.", progress = "Well, did the nomads \"volunteer\" up those water pouches for you?", completion = "Excellent, the power source is yours.  Now, it isn't completely designed for use in a science kit like that, so you'll only have a limited amount of time before all the data you collect will go kablooey!\n\nWhen you collect everything you need for whatever it is you are doing, bring it to me and I'll shut it down properly.  You'll have at most two hours to get what you need to get done, done.\n\nIf you don't get it done in time, I can always sell you another power source to try again.  You heard me - sell!", objectives = "Bring 5 Wastewander Water Pouches to Chief Engineer Bilgewhizzle in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[380] = { id = 380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Night Web's Hollow", description = "One of our greatest struggles is obtaining the natural resources we need to survive. Gold was scarce even in the height of the Alliance's power.\n\nThere is a gold mine to the northwest that has been overrun with spiders. We need gold from the mine, but we can't very well get it while the spiders are crawling around in there. I've not much manpower to commit to the task, so we'll just have to do it little by little.\n\nGet up there and see what you can do for us, {name}.", progress = "Be wary of the spiders' venom, {name}. If you feel a sharp burning, you may want to have it looked at.", completion = "Hmm, well, it's a start. It'll take a few weeks or months to fully clean out the infestation. After that, we'll have to get down there with some torches to burn away the webbing.\n\nYou've done your duty well, {name}, I'm sure I can find something else for you to do.", objectives = "Executor Arren wants you to kill 10 Young Night Web Spiders and 8 Night Web Spiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[381] = { id = 381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Crusade", description = "You'll be happy to know we appear to be making progress in the mine, thanks in no small part to your efforts.  We can now turn our eyes to other concerns.\n\nMy scouts have reported that a detachment of the Scarlet Crusade is setting up a camp southeast of here. The Scarlet Crusade is a despicable organization that hunts us, and they will not rest until every undead--Lich King's Scourge or no--is destroyed. We must strike first!\n\nBe careful, their unholy zeal makes them dangerous adversaries.", progress = "Those fools... They happily send themselves to their own graves.", completion = "If only they listened to reason, eh, {name}? Perhaps we could sit them down for reasonable discourse... ha!\n\nLight-blinded fools.", objectives = "Bring Executor Arren 12 Scarlet Armbands from Scarlet Converts and Scarlet Initiates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[382] = { id = 382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Red Messenger", description = "Reports from my superiors in Brill indicate that an agent of the Scarlet Crusade was dispatched from the Scarlet Monastery and sent here to Deathknell. According to the reports, the messenger possesses important information on his person. I do not have further details, but whatever it is, we must have it!\n\nYou're the most qualified person I have to send, {name}. Find that messenger and bring me whatever information you can find.", progress = "How goes your mission, {name}?", completion = "Hmm... Let's see what you've got...\n\n<He begins to rifle through the documents you recovered.>\n\nSome news of their exploits against us... Worthless. Scouting reports... New orders, \"Continue to build up a camp near the ruined city...\" Nothing we didn't know already... Ah, what's this? A map of the dispositions of some of their field commanders and agents! We can use this.", objectives = "Kill Meven Korgal, the messenger, at the Crusader camp, then return any information you find to Executor Arren.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[383] = { id = 383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vital Intelligence", description = "These will need to be taken to my superior, Executor Zygand, in Brill. With this information, we'll be able to deal a decisive blow to the Scarlet Crusade. Your services have been useful here in Deathknell, but I need someone to deliver this to Zygand, and I believe he'll be able to find you more appropriate work.\n\nTake the road north out of Deathknell. Soon after entering Tirisfal proper, you'll hit a crossroads. Take the eastern fork, and keep going east. You'll pass Cold Hearth Manor along the way.", progress = "Yes, what do you want?", completion = "Yes, this is very good. You've done well in obtaining this information, {name}. Hmm... names of the officers in the Tirisfal Glades...\n\nImagine the blow we could deal to the morale of those bloody zealots if we were to kill their leaders in one swift strike.", objectives = "Deliver the Scarlet Crusade Documents to Executor Zygand in Brill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[384] = { id = 384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beer Basted Boar Ribs", description = "Nothing my tavern patrons enjoy more than some Beer Basted Boar Ribs!  Only problem is, the local trapper who used to bring me supplies enlisted in the King's Army to help with the war on the Alliance front. \n\nMaybe you can help me out?  If you bring me six crag boar ribs and a Rhapsody Malt from the tavern here, I'll give you the family recipe for my famous Beer Basted Boar Ribs, not to mention a free sample!  The secret's in the Malt!", progress = "I'm going to need six crag boar ribs and a mug of Rhapsody Malt, {name}.", completion = "The Malt is brewed, the Boars are dead\nAnd before all is done and anything said\nWe will have to fight for first dibs\nOn these savory Beer Basted Boar Ribs!", objectives = "Ragnar Thunderbrew in Kharanos wants 6 Crag Boar Ribs and a mug of Rhapsody Malt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[385] = { id = 385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crocolisk Hunting", description = "Many a hunter is attracted to Loch Modan to hunt our famous crocs. There are always merchants who seek out crocolisk skins for clothing items or armor, and there are also some who enjoy the taste of their meat.\n\nWe do some trade in this, but not a huge amount, as the crocolisks are ferocious and have entrenched themselves on the islands in the Loch. But don't let me dissuade you, it's quite an experience, wrestling with the jaws of the beasts.\n\nWhy, this one time...", progress = "Did I tell you about the time I almost lost my hand to one of the crocs? Nasty bugger it was, teeth like knives. But I was lucky... Jammed the brute's jaw shut with my knife. Still have the knife around here somewhere...", completion = "Well now, these are excellent specimens you collected, {name}. Good money for high quality materials, that's for sure.", objectives = "Get 5 pieces of Crocolisk Meat and 6 Crocolisk Skins for Marek Ironheart at the Farstrider Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[386] = { id = 386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Comes Around...", description = "Targorr the Dread served under Gath'Ilzogg as supreme Executioner.  His methods were ruthless, even by filthy orc standards.  Men who fought bravely to defend the Kingdom were tortured on his whim.  Now he is being held in the Stormwind Stockade, sentenced to die.  Yet something is amiss.  One of the bureaucratic nobles put a hold on his execution.  I am sure foul play is in the works.\n\nPut an end to Targorr the Dread, {name}.  Travel to The Stockade and behead him before trickery is upon us.", progress = "Have you been to Stormwind yet, to The Stockade?  I fear whatever trickery that has kept Targorr the Dread alive for this long will eventually bring about his freedom.  He was sentenced to die, {name}, not act as some political pawn on a noble's whim.", completion = "Targorr the Dread has finally met his fate.  I for one am glad to hear the beast now knows what it is like to be on the receiving end of Death's ruthless grip.  You have done well, {name}.  Sometimes the truest justice can only be found outside the courtroom and beyond the clouded vision of politics.", objectives = "Bring the head of Targorr the Dread to Guard Berton in Lakeshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[387] = { id = 387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quell The Uprising", description = "The uprising must be quelled!  I need your assistance.  If word gets out that the prison is overrun I will lose my job!  This is a case of foul play if I've ever seen one.  But what's important now is forcing these prisoners into submission for the safety of Stormwind.\n\nThe punishment for insurgency is death.  Kill some of these deviants!  That ought to get things under control.", progress = "The Stockade is still overrun!  These Defias Rats must be shown that their actions will not be tolerated.  Now get back down there and show some force!", completion = "Your efforts in The Stockade were valiant, {name}.  It's obvious this problem is bigger than the both of us.  But you have performed well and for that I am thankful.", objectives = "Warden Thelwater of Stormwind wants you to kill 10 Defias Prisoners, 8 Defias Convicts, and 8 Defias Insurgents in The Stockade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[388] = { id = 388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Color of Blood", description = "Bitterness flows through my veins like a cold river.  My grandson, Mac, was such a good boy.  A mere 14 years old.  When the army was sent off to the front, Mac took up arms to defend the city.  He was a guard in The Stockade, where the Defias gang is locked up.  Mac reprimanded some of the prisoners for tearing their wool blankets to make scarves, a symbol of their gang.  For that Mac was stabbed in the back.\n\nI want revenge.  Bring me 10 of their precious Wool Bandanas.  They are the color of blood.", progress = "I see you are back, {class}.  Have you collected 10 Red Wool Bandanas from those Defias Scum in The Stockade yet?", completion = "So these bandanas -- filthy tokens of corruption -- are what my Mac had to die for?  Such a waste.  Such a tragic sacrifice. \n\nBut alas, I cannot return to the past.  Just know, {name}, that you have brought my family justice through your deeds.", objectives = "Nikova Raskol of Stormwind wants you to collect 10 Red Wool Bandanas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[389] = { id = 389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bazil Thredd", description = "VanCleef and I were members of the Stonemasons Guild. Our main project was to rebuild Stormwind after the War.\n\nWhen we had finished our duties, we were cheated. The nobles refused to pay us for our work. Some of the more senior of the Stonemasons were offered governmental jobs, but VanCleef refused it out of loyalty to all the Stonemasons. He led a riot and left the city, swearing revenge.\n\nHis lieutenant, Bazil Thredd, might know more about VanCleef's plans. He's being held prisoner in the Stockade.", completion = "What in the Light do you want? Can't you see we have a crisis here?\n\nBazil Thredd?! Why would you want to speak with that bastard? How am I supposed to know you're not one of his cronies, come down to help with his bloody riot? If all the blasted cells weren't open, I might throw you in one for a while!", objectives = "Speak with Warden Thelwater in the Stockade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[391] = { id = 391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stockade Riots", description = "Let's get one thing straight, {name}: I don't trust you. But, with the situation as it is, you probably won't make a difference.\n\nSo here's how it's going to be: go down there and have your talk with Thredd. If you're really on our side, then kill him and bring me his head when the job's done. And if it turns out you're on his side, and don't come out... when we find you, you'll die along with the rest of the maggots.", progress = "Either you bring me Thredd's head, or I'll take yours, understand, {name}?", completion = "Without Thredd to lead them, hopefully the riots will be more controllable. We shall see.\n\nI must say, after a half hour, I hardly expected you to come out, but it seems I misjudged you.\n\nI'd guess, then, that you didn't get much useful information out of him? But I know a thing or two that might be of interest to you about Thredd's activities.", objectives = "Kill Bazil Thredd and bring his head back to Warden Thelwater at the Stockade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[392] = { id = 392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Curious Visitor", description = "During the first years of Thredd's imprisonment, he never had any visitors. I figured that he was no longer of use to the Brotherhood, so they abandoned him.\n\nAnyway, a few months ago, that all changed; he started to get regular visits... once, maybe twice a week. It was a strange man--the quiet type. I had my suspicions, but all his papers checked out.\n\nHis documents claimed his name was Maelik; here's his description. I don't think he'll be coming to visit Thredd anymore.", progress = "Yes, {name}? What have you found?", completion = "Hmm. Maelik? No, the name doesn't sound familiar and neither does this description. But it could be anybody! A former Stonemason, one of the Defias Brotherhood... Though if he is as well connected as Thelwater suggests, perhaps someone else might recognize him. Let me think.", objectives = "Bring the Sealed Description of Thredd's Visitor to Baros Alexston in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[393] = { id = 393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow of the Past", description = "I really haven't a clue, {name}. There is someone else who might be able to help you, and it so happens that he owes me a favor for--well, let's not get into that. Master Mathias Shaw of SI:7 can be found in the barracks in Old Town. Shaw has his thumb on most of the shady, or underhanded dealings of the city.\n\nIf anyone knows, it'd be him.", progress = "Greetings. Of what service can I be to you, {class}?", completion = "What? What's this? Yes, I think I do know who this man is, but his name is not Maelik. Assassins wear many names and many masks, discarding them as they lose their usefulness. Another alias known to be used by this man is Marzon; though even that is surely not his true name.\n\nRegardless, he is an assassin and I know a good deal about him.\n\nMarzon is currently under the employ of Lord Gregor Lescovar, a lord of shady reputation, even given the corruption of the nobility of Stormwind.", objectives = "Bring the Sealed Description of Thredd's Visitor to Master Mathias Shaw in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[394] = { id = 394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Head of the Beast", description = "Find Shaw in Old Town. Let him know that the Lescovar threat has been dealt with and about your involvement in the Lord's plots against the city. I'm sure he'll be proud to have another hero among Stormwind's citizens.\n\nHe'll more than likely send you off to meet with the Prince or some other noble. Don't let it get to your head, {name}. The nobles can think they rule the city all they want, but some things remain out of their hands.", completion = "He is dead, then? Your justice was swift, {name}. I pray to the Light that I never become your quarry!\n\n\n\nI mean no criticism, {name}. How could I, being the master of all assassins? But in truth, you have done the people of Stormwind a great service, and for that, I thank you.", objectives = "Speak to Mathias Shaw in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[395] = { id = 395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brotherhood's End", description = "Ah, I almost forgot. Alexston came while you were away, he wished to speak with you. No doubt he wishes to report the goings-on of the Defias Brotherhood to the nobles.\n\nA bit of advice, {name}: if anyone should ask, I would provide all details but that it was your hand that slew Lescovar. Trust me. I am... acquainted... with the ways of such things.\n\nAnd as far as Trias goes, well, speak to no one of him... ever... if you can help it.", completion = "It's good to see you, {name}. I have heard that Lord Gregor Lescovar was found dead not long ago.\n\nIt would seem that you were successful in your mission. You have my gratitude that you have saved me, and many others, from VanCleef's revenge.", objectives = "Speak with Baros Alexston in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[396] = { id = 396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Audience with the King", description = "I have prepared a report for the King. I believe you should be the one to deliver it to him, along with an account of your findings. Do not worry, there is no doubt that he will commend you for doing your duty to the people of Stormwind.\n\nYour audience is scheduled soon, so you'd best hurry, it's a bit of a ways to Stormwind Keep.", progress = "{name}, yes? I was informed by Baros Alexston that you would be coming. I must say, I am most interested in what you have to say.", completion = "You are to be commended for the service you have done for Stormwind, {name}. If VanCleef had been successful in his machinations, he would no doubt have done considerable harm to the kingdom--something we must obviously avoid.\n\nTake this, {class}, as a token of the King's appreciation. I am only sorry he cannot present it to you himself, but he is away on a diplomatic mission and shall not return for some time.", objectives = "Deliver Baros Alexston's report on the Defias Brotherhood to King Varian Wrynn in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[397] = { id = 397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Have Served Us Well", description = "I hear Lord Wishock enjoyed his beverage.  \n\nYou have served us well, {name}.  The Warlocks of Stormwind will be able to practice our ways without disturbance, thanks to you.  For your efforts, I have prepared a special gift for you.  Speak with my servant, Zggi, and claim your reward.", completion = "Master says give gift to {name}.  Zggi wants to keep nice gift but Zggi knows better than to betray Master.", objectives = "Speak with Zggi, the servant of Zardeth the Blackclaw, to claim your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[398] = { id = 398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Maggot Eye", description = "Wanted: Maggot Eye!\n\nA foul beast, even by Gnoll standards, Maggot Eye has been sentenced to death for his crimes against The Forsaken.  This despicable villain has been stealing corpses for use by the Lich King's army.  Maggot Eye was last seen pillaging the lands near Garren's Haunt to the north of Brill.\n\nThe town of Brill hereby offers a reward to the capable soul who can carry out the execution.  Show Executor Zygand the villain's paw once the deed is done.\n\nMercy is for the weak.", progress = "Yes?", completion = "Maggot Eye's dastardly acts have finally been avenged.  Maybe your acts of valor will send a clear message to those who wish to bring harm to our people.  On behalf of the town of Brill I thank you, {name}.", objectives = "Kill Maggot Eye and return to Executor Zygand in Brill with his paw for a reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[399] = { id = 399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Humble Beginnings", description = "It seems an eternity since I was a boy working the farm in Westfall. They say you can never go back, and it's true. Doubly true in my case, my family's home has been burned down and taken over by thieves.\n\nI have spoken with my father about the fate of some of my possessions, including my first compass. He was unable to save them. However, he also says that they should be hidden away on the farm.\n\nYou'll find the Alexston Farmstead west of Sentinel Hill. Perhaps you could go and retrieve it for me?", progress = "{name}! Did you have any luck?", completion = "Oh, thank you, {name}! It's of no practical use to me, but the sentimental value... Needless to say, thank you for bringing this to me... at some cost to your own well-being, not to mention the time it took to go all the way down to Westfall. You have my gratitude, and have this as a token of my thanks.", objectives = "Go to Baros Alexston's house in Westfall and search for his compass, then return it to him in Cathedral Square of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[400] = { id = 400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools for Steelgrill", description = "Beldin Steelgrill owns the local mechanic shop, and he's the best siege engine tech there is!  But he's not forgiving to his tools.  I swear he almost breaks more arclight spanners than we can supply him with!\n\nWe just filled his last order for tools.  If you deliver it to him I'm sure he'll make it worth the effort.\n\nHis shop, Steelgrill's Depot, is just northeast of Kharanos.  And it's a local haunt for veteran siege engine pilots, so keep your ears open for opportunities while you're there.", progress = "Hm?  You look a little young to be a siege engine pilot.  But no matter...do you need something fixed?\n\nWell take a number and get comfortable.  I'm working on a couple engines right now and won't have time for another job for at least a few days.\n\nOr, were you here for something else...?", completion = "You have my tools?  Well done, lad, well done!  I just broke my last fang-ratchet an hour ago and I need one of those to finish repairs on Pilot Stonegear's siege engine.  You did a good thing by lugging those tools here, {name}.\n\nHere, take these coins for your help.", objectives = "Deliver Steelgrill's Tools to Beldin Steelgrill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[401] = { id = 401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wait for Sirra to Finish", description = "I'm almost finished translating that note.  If you come back in a few moments I should be done.", completion = "There we are.  It's translated...\n\n<The air grows heavy, as if a thick, black curtain is drawn over the land...>", objectives = "Wait a moment, then speak with Sirra Von'Indi again.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[402] = { id = 402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sirra is Busy", description = "I'm sorry, but with the town in the state it's in I'm afraid have other duties to attend to.  Perhaps later, if we survive, I can finish this translation.", sourceObjective = "Check back with Sirra later to see if he's still busy.I'm sorry, but with the town in the state it's in I'm afraid have other duties to attend to. Perhaps later, if we survive, I can finish this translation.", sourceObjectiveStatus = "unverified-source-field" }
quests[403] = { id = 403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guarded Thunderbrew Barrel", sourceObjective = "This barrel of ale is guarded by Jarven Thunderbrew.  As long as he's in the basement, no barrels may be disturbed.", sourceObjectiveStatus = "unverified-source-field" }
quests[404] = { id = 404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Putrid Task", description = "Scourge have trickled into Tirisfal Glades and have infested the area west of Brill, near the old bridge.\n\nGo there and beat back the rotting dead and ravaged corpses you find.  Scatter their bones and bring back their putrid claws, and the Deathguards will reward you.", progress = "Have you completed the task with which I have charged you?  Do you have those putrid claws?", completion = "Well done.  I regret not being there to see you smash those {race} into rotting pulp!", objectives = "Bring 7 Putrid Claws to Deathguard Dillinger in Brill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[405] = { id = 405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prodigal Lich", description = "Bethor Iceshard, a high-ranking and powerful mage in the Undercity to the south, commands me to send him an agent with proven worth against the Scourge.  You, {name}, will be that agent.\n\nPresent these orders to Bethor.  He will then instruct you on your mission.  I don't know its details, but it deals with recruiting a wayward Lich.  And it will be dangerous.\n\nSo ready yourself, {class}.  You must not fail.\n\nYou may find Bethor in the Magic Quarter of the Undercity.", progress = "Greetings.  Either you do not know who I am, or your business with me is urgent.\n\nBecause if neither of these were true, then you would not be foolish enough to disturb me...", completion = "Ah, you are the agent sent by Magistrate Sevren.  Then yes, your business with me is crucial.\n\nI trust Sevren has mustered someone suitable for my task...but we shall see.", objectives = "Present Sevren's Orders to Bethor Iceshard in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[407] = { id = 407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fields of Grief", description = "Harmless pumpkins, right?  Or so it would seem.  If we are to defeat Arthas's advances from the North and the Human infestation from the South we need to start realizing the full potential of our gift of undeath.\n\nWith a little ingenuity a simple pumpkin becomes an agent for our Dark Lady.  This pumpkin, laced with my latest formula, will prove to be quite a treat.\n\nYet another Scarlet Zealot has been captured and is being kept in the cellar of the Gallow's End Tavern.  Take this pumpkin to the fool.", progress = "Stay away, foul and unholy creature!  May the Light protect me!  The Scarlet Crusade shall rid Azeroth of your. . .\n\n. . .oh wait.  Is that food for me?  I am so hungry. . .", completion = "By the Light!  Finally some food!  Sweet, sweet pumpkin. . . .", objectives = "Take the Laced Pumpkin to the Captured Scarlet Zealot who is being held in the cellar of the Gallow's End Tavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[408] = { id = 408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Family Crypt", description = "The Agamand Mills area has become a foothold for the Scourge.  Their strongest point is the Agamand Family Crypt where their local military leader, a skeleton named Captain Dargol, has headquartered.  With Necromancy he has raised the ancestors of the Agamands and plans to use them against us.\n\nThis cannot pass, and you must stop it.  Travel to the Agamand Family Crypt and defeat the raised Agamand ancestors.\n\nAnd, bring me the skull of Captain Dargol.", progress = "Time is not a luxury we have, {name}.  With each passing hour, the Scourge's hold on Tirisfal Glades grows more firm.", completion = "Your actions struck a telling blow against the Scourge.  And your victory will not go unnoticed - not by the Forsaken, nor by our enemies.\n\nContinue the struggle as we all do, {name}, and one day we will drive the Lich King himself from Azeroth!", objectives = "Kill 8 Wailing Ancestors and 8 Rotting Ancestors.\n\nKill Captain Dargol, and bring his skull to Magistrate Sevren in Brill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[409] = { id = 409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Allegiance", description = "You say you are not bound by the will of the Lich King, and the enchantment Bethor placed upon my book corroborates this.  But before I believe you I must have proof that you are enemy to the Scourge.\n\nThere is an old, bloody altar just off the southern coast of this island.  it is used by a powerful Scourge agent, Lillith Nefara.\n\nTake a Candle of Beckoning from this crate here.  Light it on the altar and Lillith will awake.  Destroy Lillith, and I will believe you are the Lich King's foe.", progress = "I await proof of your allegiance, {class}.", completion = "You have defeated Lillith Nefara, proving you are an enemy of the Scourge.  Incredible.\n\nI had believed I was the only {race} with free will, but you have shown me there are others who have broken the Lich King's domination.", objectives = "Obtain a Candle of Beckoning.\n\nSummon Lillith Nefara and kill her.\n\nReturn to Gunther on his island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[410] = { id = 410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dormant Shade", progress = "This is an old, beaten, bloody table.", completion = "You place the Candle of Beckoning upon the table and light it..." }
quests[411] = { id = 411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prodigal Lich Returns", description = "Take this Nether Gem to my old comrade Bethor.  It will let us communicate ... and I have much to tell him.", progress = "Have you returned Gunther's book?  Has he responded?", completion = "You convinced him to join us!  You have done a great deed for the Forsaken, {name}.  The Dark Lady will be informed.", objectives = "Bring the Nether Gem to Bethor Iceshard in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[412] = { id = 412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Recombobulation", description = "Upon further analysis of the Gnomeregan situation, it would appear as though we not only failed to eradicate the troggs but we also happened to turn most of the gnomish race into horrific, mindless, evil-doing leper gnomes.\n\nOzzie and I plan to reverse the horrible leper effect with our latest invention: The Recombobulator.  The machine is almost complete but we are in dire need of some Restabilization Cogs and Gyromechanic Gears.  Retrieve some from the leper gnomes out front of Gnomeregan for us.", progress = "The Recombobulator will be up and running as soon as we have sufficient Restabilization Cogs and Gyromechanic Gears.", completion = "These Gyromechanic Gears and Restabilization Cogs are in perfect accordance with Ozzie's schematics for the Recombobulation Device.  Once I add some hydrolubricant to the inner combustion pistons, adjust the crank-o-ratchet and increase of the viscosity of the electrogum gel, the gnomish race will be as good as new.", objectives = "Bring Razzle Sprysprocket in Kharanos 8 Restabilization Cogs and 8 Gyromechanic Gears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[413] = { id = 413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shimmer Stout", description = "I'd like my brother Wellart to try my new Shimmer Stout.  He's a Mountaineer stationed in the southern guard tower, one of two towers on the border to Loch Modan.\n\nHe may not be a brewer like the rest of us Barleybrews, but he loves his drinks and I know he'll like this one.\n\nCan you bring him this Barrel of Shimmer Stout for me?", progress = "Hello, {class}!  And what business takes you all the way out here?\n\nSomething exciting, I hope.  I haven't been in a good fight in days, and this barrel of ale is almost dry...", completion = "<Mountaineer Barleybrew tastes the Shimmer Stout...>\n\nOh.  Whoa!  This stuff really puts a shine in your eyes.  I feel like I can see in the dark!", objectives = "Take the Barrel of Shimmer Stout to Mountaineer Barleybrew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[414] = { id = 414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stout to Kadrell", description = "I've been drinking more of that Shimmer Stout my brother made - it's great stuff!  I want a fellow Mountaineer to try it.  His name's Kadrell, and he's usually patrolling the road through Thelsamar in Loch Modan.\n\nTo get to Thelsamar, go southeast through the tunnel, then turn northeast when the path forks into a road.  Follow that road straight into Thelsamar.\n\nGive Mountaineer Kadrell this cask of Shimmer Stout and see what he thinks!", progress = "Greetings, {class}, and welcome to Thelsamar!", completion = "Now, let me have a taste...\n\nMagni's Beard!  This stuff gets your head turning!  And it lightens the limbs, too.\n\nI feel like I can fly!", objectives = "Take the Cask of Shimmer Stout to Mountaineer Kadrell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[415] = { id = 415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rejold's New Brew", description = "Rejold Barleybrew at Brewnall Village has been asking for you.\n\nHe wants to talk to you about a new drink he's been brewing...said something about you helping him with it.  You might want to head back to Brewnall Village and see what he has to say.\n\nThere could be some free booze in it for you...", completion = "{name}!  You know that Shimmerweed you brought me?  Well I used it in a few recipes I've been working on, and one of them turned out great!\n\nHere, try it out and tell me what you think...", objectives = "Speak with Rejold Barleybrew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[416] = { id = 416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rat Catching", description = "We have a real infestation problem to the west.  Tunnel rat kobolds have moved into the foothills, setting up dens and fouling our land with their filth!\n\nWe want them eliminated.  Hunt them, bring me their ears and earn their bounty.\n\nYou can find tunnel rat kobolds and their dens west of Thelsamar, littered along the mountainside.", progress = "Hail, {name}.  How goes the rat catching?", completion = "Ugh!  When I asked for those ears I didn't realize they'd smell so bad!\n\nHere's your reward, {name}.  Well done.", objectives = "Bring 12 Tunnel Rat Ears to Mountaineer Kadrell in Thelsamar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[417] = { id = 417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pilot's Revenge", description = "Hildelve wrote in his journal that he was attacked by Mangeclaw, a \"huge Ice Claw Bear.\"  He drove off the beast, but not before it mauled him savagely.\n\nJudging from the state of Hildelve's body, Mangeclaw must have later returned and killed him.\n\nHowever, Hildelve wrote in his journal his one, final wish:\n\nRevenge against Mangeclaw.", progress = "Hello, {name}.  Do you have word of my friend Hildelve?", completion = "This is grim news, for Hildelve was a good friend.  And I wish I could have been there with you when you found the beast, Mangeclaw!\n\nThank you, {name}.  Your deed will be remembered by the pilots of the Ironforge Siege Brigade.", objectives = "Kill Mangeclaw.\n\nBring his Mangy Claw and Hildelve's Journal to Pilot Hammerfoot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[418] = { id = 418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thelsamar Blood Sausages", description = "There's never a shortage of empty bellies here in Thelsamar, kids running in and out, workers from the excavation coming in after  a hard day's work. We're famous for our blood sausages, I don't suppose you've ever tried them?\n\nNo? Well, around here you've got to work for your meals, and don't think just because you're a fancy {class}, you'll be any exception.\n\nI'll need bear meat, boar intestines for the casings, and spider ichor for spice. You get me some of those, and leave the cooking to Vidra!", progress = "I'm all ready to start cooking, do you have the ingredients for me?", completion = "Trust me, it seems a lot harder than it looks, but...\n\nOh, I've never known someone to take much interest in the making of sausages, but I'll give you the recipe just in case. Here you go, mind you eat them fresh!", objectives = "Bring 3 pieces of Bear Meat, 3 Boar Intestines, and 3 Spider Ichor to Vidra Hearthstove in Thelsamar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[419] = { id = 419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Pilot", description = "My friend and fellow Siege Engine pilot, Mori Hildelve, is lost in the hills.  We were looking for a rare ore that's needed for a high-grade blastpowder, and during our search he drove his engine up a steep hill and busted it!\n\nStill convinced that ore was in these mountains, Hildelve charged me to guard our engines while he continued on foot, searching.\n\nIt's been days, and I've heard some beastly growls in the hills at night.  Mori's tough as nails, but I'm worried.\n\nPlease, {name}.  Find him.", completion = "Here is the corpse of a dwarf -- mauled, frozen, and picked clean by mountain scavengers.  Clutched in its hand is a book containing the roughly scribbled notes of Mori Hildelve.  And around its frame, still in superior condition, is a Brigadier's Vest.\n\nThis grisly scene must have been where the Siege Engine pilot met his end.", objectives = "Find Pilot Hildelve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[420] = { id = 420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Senir's Observations", description = "The troggs in the tunnel are extremely hostile, and haven't shown any hesitation in attacking travelers through the tunnel. You seem tough enough, though, so you should probably be safe.\n\nDirections? If you're going to speak with Senir, you'll find him in Kharanos.\n\nMake your way through the tunnel, and after you come out on the other side, just keep following the road, it'll run right into Kharanos.", progress = "How are you? Like to share a drink with me, perhaps? Not much else to do in the cold.", completion = "What's this? Ah, my brother's report. Hmm...\n\nI told him to be sparing with the use of the King's name, but he didn't listen. No harm, I suppose, though it's sure to ruffle some feathers in the Senate. Not that those weren't some feathers that needed ruffling! Hah!\n\nNonetheless, I guess that means that I should send my report on to Ironforge as well, but I must admit I'm a bit behind. Bloody cold.\n\nI should have some work for you later, if you're interested.", objectives = "Deliver Grelin's report to Senir Whitebeard in Kharanos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[421] = { id = 421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prove Your Worth", description = "Lady Sylvanas has charged Varimathras with the conquering of the human and dwarven lands to the south.\n\nBut that fool, Arugal -- charlatan of Dalaran and now cursed beast of Shadowfang Keep -- let his reckless magic wreak havoc with the strategic stronghold of Silverpine Forest.\n\nI need someone skilled in the ways of combat to help clean up Arugal's mess.  Prove yourself to me by killing 5 Moonrage Whitescalps.  The wretched beasts can often be found just off the road, down the hill below.", progress = "If you wish to prove yourself to me, you must kill 5 Moonrage Whitescalps.  Accomplish that task, and I will see to it your skill is put to more worthy assignments.", completion = "You have served me well, {class}.  It is obvious to me that you will be a worthy aide to me as I prepare to rid Silverpine Forest of Arugal's curse.", objectives = "Dalar Dawnweaver at the Sepulcher wants you to kill 5 Moonrage Whitescalps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[422] = { id = 422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arugal's Folly", description = "How Arugal gained acceptance within the Kirin Tor is beyond me.  His spell-casting knowledge seemed as transparent as a blown glass bauble.\n\nWhat's important now is learning exactly what magic Arugal used so that I can turn it against him and secure Silverpine Forest for the Dark Lady.\n\nArugal first stayed at the wheat farm just north of the bridge.  One of the Deathstalkers reported seeing some spellbooks but could not secure them.  Retrieve for me the spell labeled Remedy of Arugal from those books.", progress = "Before I know what we are dealing with here, {class}, I need to study the spell known as Remedy of Arugal.  Bring it to me now or I shall be forced to find myself a worthy servant.", completion = "This is precisely the spell I was in search of, {class}.  If your dedication to The Dark Lady's cause remains infallible you will find you have quite a future amongst The Forsaken.", objectives = "Retrieve the Remedy of Arugal for Dalar Dawnweaver at the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[423] = { id = 423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arugal's Folly", description = "After examining Arugal's work my worst suspicions were confirmed.  The old hack was not qualified to clean chamber pots in Dalaran let alone represent the Kirin Tor in its most dire hour.  Fools!\n\nArugal used enchanted items to reinforce his weak magic.  I need to examine these items first hand.  Travel forth and slay Moonrage Gluttons and Moonrage Darksouls until you have collected enough of their enchanted shackles for my research.  The foul creatures have been seen to the north and east.", progress = "I will need 6 Glutton Shackles and 3 Darksoul Shackles before I can assess the situation and devise a final solution for Arugal.  Now heed your bidding and slay Moonrage Gluttons and Moonrage Darksouls until you have what I need.", completion = "I hope I can acquire enough energy from such a limited sample.  Perhaps I should have had you get more shackles.\n\nNonetheless, you showed great skill in collecting these, {class}.", objectives = "Bring 6 Glutton Shackles and 3 Darksoul Shackles to Dalar Dawnweaver at the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[424] = { id = 424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arugal's Folly", description = "It will indeed take me longer than I had thought to uncover the dark secrets behind the enchantments Arugal was using.\n\nBut in the meantime I need you to take care of a slight problem our Darkstalkers have discovered.  It seems that Arugal let his magic spread to the Deep Elem Mine in the hills to the southeast.\n\nThe mine would prove to be quite a resource for Varimathras's advance.\n\nI want you to behead the tainted foreman of the mine, Grimson the Pale.  With his death, the mine shall be ours.", progress = "Has Grimson the Pale been slain?  Varimathras will not be pleased if we ignore his bidding.", completion = "Most excellent.  The mine will provide superb resources for our forces as we spread throughout Silverpine and into Azeroth.", objectives = "Kill Grimson the Pale and bring his head to Dalar Dawnweaver at the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[425] = { id = 425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ivar the Foul", description = "My brother Quinn and I were tasked to recon Silverpine Forest and report to High Executor Hadrec.  But we didn't get far -- when moving through this farm we were attacked by the ghoul Ivar the Foul.\n\nWe escaped from Ivar, but he seriously mauled Quinn.  He's healing from the potion you gave him, but Ivar may return before Quinn recovers.\n\nKill Ivar so Quinn will have time to heal.  Ivar is usually in the barn yonder, waiting for my guard to drop.", progress = "Have you killed Ivar the Foul?  If you won't do it for me and my brother, then do it for the Forsaken.", completion = "Ah, thank you.  You have my gratitude, {name}.\n\nAnd I will include you in the report I make to my superiors.", objectives = "Kill Ivar the Foul, and bring Ivar's Head to Rane Yorick at the Ivar Patch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[426] = { id = 426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mills Overrun", description = "The Scourge are trying to form a base at the Agamand Mills.  If they do, then they can stage further attacks within Tirisfal.\n\nThe orders have been given.  The Scourge in the Mills must be destroyed.\n\nGo to the Mills.  Collect Notched Ribs from Rattlecage and Cracked Skull Soldiers, and Blackened Skulls from Darkeye Bonecasters.\n\nTo get to the Mills, follow the road west.  After crossing the bridge, take the next fork north then keep going north.  When you see windmills, the battle will begin.", progress = "Our battles with the Scourge wage on, {name}.  Do your part and throw those cursed, mindless {race} back into the Plaguelands!", completion = "Your efforts in the war are felt among us, {name}.  I will not thank you for doing what is necessary, but the Deathguards of Tirisfal will remember your name.", objectives = "Gather 5 Notched Ribs and 3 Blackened Skulls, then return to Deathguard Dillinger in Brill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[427] = { id = 427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At War With The Scarlet Crusade", description = "The documents Executor Arren provided are just the break we needed in our battle with the wretched Scarlet Crusade.  We now know their exact locations throughout Tirisfal Glades.\n\nBut the Deathguard has larger concerns.  The Lich King's army grows in number each night.  We need someone with \"initiative\" like yourself to drive the Scarlet Crusade to the grave.\n\nProve to me you are capable of serving The Dark Lady by travelling west to the tower past the Solliden Farmstead and slay 10 Scarlet Warriors.", progress = "If you wish to prove your worth to The Dark Lady, slay 10 Scarlet Warriors, {class}.", completion = "Most excellent, {class}.  Your skill in the art of combat is undeniable.", objectives = "Executor Zygand of Brill wants you to kill 10 Scarlet Warriors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[428] = { id = 428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Deathstalkers", description = "A couple weeks ago two of our Deathstalkers, Rane and Quinn Yorick, were sent on a reconnaissance mission through northern Silverpine.  We have not heard from them.\n\nThey may have become victim to the Scourge, though if that is true then I want it confirmed.  Find these Deathstalkers.\n\nTheir first objective was to scout the farms in northern Silverpine.  You should begin your search there.", completion = "You found us!  And not a moment too soon...", objectives = "Find the Deathstalkers Quinn and Rane Yorick.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[429] = { id = 429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Hearts", description = "My brother Quinn was badly hurt by the ghoul, Ivar the Foul, and I don't know if he will heal properly without magical aid.  Although I am not an apothecary, I do know that our apothecaries can make healing potions from the discolored hearts of worgs.\n\nGather such hearts and take them to Apothecary Renferrel at the Sepulcher to the south.  Then return here with the potion.\n\nYou can find plenty of worgs between here and Malden's Orchard to the east.", progress = "My time is short, {class}, for the Dark Lady has charged me with a grave task.", completion = "<Renferrel takes the hearts.>\n\nIt is troubling to hear our Deathstalkers have failed their mission.\n\nLet us hope that these failures are rare.\n\nI'll give you the potion in a moment, but here is its recipe - if those Deathstalkers find themselves in need of future aid, then perhaps you can give it yourself.", objectives = "Gather 6 discolored worg hearts and bring them to Apothecary Renferrel at the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[430] = { id = 430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Quinn", description = "Here is the potion to aid in Quinn Yorick's recovery.\n\nNow if you will excuse me, I have very important work to continue...", progress = "My sister told me you were here to aid us.  Is that true?", completion = "<Quinn takes the potion and drinks it.>\n\nYes, I can feel it working.  I will soon be able to travel.\n\nYou have done me a great favor, {name}.", objectives = "Bring Quinn's potion to Quinn Yorick at the Ivar Patch, north of the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[431] = { id = 431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candles of Beckoning", sourceObjective = "You grab one of the candles and place it in your pack.", sourceObjectiveStatus = "unverified-source-field" }
quests[432] = { id = 432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Blasted Troggs!", description = "Those Light-blasted troggs, turning my work site into a wreck! Look at that, there goes another barrel of powder!\n\nOhhh, I wish I could go down there and wring every one of their scrawny little necks! I want to kill them all!\n\nThis can't be good for my health, all this stress and anger... What have they left me with? Nothing!\n\nI'd kill them myself, but my aim's no good anymore! You go into the quarry and kill some of the filthy buggers! I'll pay you! Just hurt them, kill them!", progress = "It makes me so mad! Grrr...", completion = "Well, that makes me feel a little better...\n\nBut I won't be happy until they're all dead! All of them!", objectives = "Kill 6 Rockjaw Skullthumpers for Foreman Stonebrow at the Gol'Bolar quarry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[433] = { id = 433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Public Servant", description = "As a member of the Senate and the Explorers' League, I've taken it upon myself to take care of this part of the trogg infestation that has gripped our lands.\n\nThey've certainly made a mess of Gol'Bolar quarry, and for no reason. As we dug deep into the earth, they poured out, destroying our equipment and driving the miners out. There's not much for us to do but to exterminate the lot of them, rebuild, then get back to work.\n\nIf you help me with the troggs, I'll gladly recompense you for your time.", progress = "If we can remove the troggs from Gol'Bolar quarry, it will be the first step of many that we will have to undertake to rid ourselves of this menace.", completion = "It is a start. Hopefully we can take advantage of it, and move some Mountaineers in to secure the area. Then we can begin to restore our infrastructure and get the miners back to work.\n\nThank you for your assistance, {name}.", objectives = "Kill 10 Rockjaw Bonesnappers for Senator Mehr Stonehallow at the Gol'Bolar quarry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[434] = { id = 434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Attack!", description = "After I put on Spybot's disguise, he'll head in to talk to Lescovar. The guards should let him pass no problem.\n\nWhile you were getting materials for me, I took care of informing Marzon that it was time for him and Lescovar to meet again. I even dropped some false information.\n\nLescovar will dismiss his guards and wait for Marzon out here in the garden. After you catch wind of talk about the Defias, make your move. You need to kill them both before the guards return! When you're done, speak to Trias.", completion = "So it is done? Good. Thank you greatly for your discretion, {name}. You've proven worthy on more than one count. I'll be sure to keep my eyes on you and your progress within the Alliance.\n\nBe sure to keep your nose clean.", objectives = "Remain in the garden until Lord Gregor Lescovar and Marzon the Silent Blade have had their conversation. Afterwards, kill them both before returning to Elling Trias in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[435] = { id = 435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escorting Erland", description = "The wolves outside won't leave, and they eye me evilly every time I step foot out that door.  They must be incredibly hungry to think I'm worth eating.\n\nI have to report to my teammate, the Deathstalker Rane Yorick.  And to get to Rane, I'll need help against those wolves.\n\nPlease escort me!  And there are a lot of wolves out there, so we'll have a better chance if you have friends who can help...", progress = "Please be brief.  There is much danger about and we cannot stand idle in conversation.", completion = "Thank you for the aid, {name}.  I had feared Erland was overcome by the dangers of Silverpine.  With your help, I see that he has not.", objectives = "Escort Erland through the wolves, to Rane Yorick.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[436] = { id = 436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ironband's Excavation", description = "Prospector Ironband is heading an excavation of ancient ruins east of the lake.  His progress has been slow lately, especially considering all the supplies we've sent him.\n\nIronband's a stout, honest dwarf who values results, which has me worried that forces are at work against him.\n\nGo to Ironband's Excavation and speak with Magmar Fellhew.  He manages the details of the site and will know why there's a slowdown.\n\nTo get to the excavation site, go around the southern tip of the lake, then head east.", completion = "Jern wants to know what the slowdown is, eh?\n\nIronband is putting together his latest progress report with details, but I can tell you this:\n\nIt's the Troggs!!", objectives = "Speak with Explorer Fellhew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[437] = { id = 437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dead Fields", description = "Our initial scouting reports of Silverpine show the rot hides have a base at an old farm to the north, the Dead Fields.  We have sent small assaults against them, but each time they are reinforced by the banshee Nightlash, who uses her magic to rout our forces.\n\nWe want Nightlash destroyed.\n\nGo to the Dead Fields and assault the rot hides.  If you don't see Nightlash then kill the rot hides until she appears, then defeat her.\n\nHer essence will turn to dust.  Bring me that dust as proof.", progress = "Have you defeated Nightlash, {name}?  Our success against the rot hides depends on her destruction!", completion = "I heard of your successful raid against the rot hides, {name}, and this essence is proof of Nightlash's death.\n\nThe Scourge have lost ground this day.  Your value to the Forsaken grows.", objectives = "Kill rot hide gnolls at the Dead Fields.\n\nWhen Nightlash appears, kill her.\n\nBring the Essence of Nightlash to High Executor Hadrec at the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[438] = { id = 438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Decrepit Ferry", description = "{name}, we've discovered a new hive for the Scourge: the Decrepit Ferry.  The ferry lies east of the Sepulcher, and is heavily patrolled by rot hides and other undead.\n\nThere must be a reason for the Scourge's occupation of the area.  Go to the Decrepit Ferry and find out why the Scourge are there.", completion = "Heaped within this boat is a pile of wrapped corpses.  And looking east across Lordamere Lake, an opposing dock on Fenris Isle can be seen.\n\nThe fate of the corpses must lie on Fenris Isle.", objectives = "Go to the Decrepit Ferry.\n\nSearch for the reason the Scourge are there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[439] = { id = 439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rot Hide Clues", description = "Among the corpses a hand protrudes, unwrapped.  It is the hand of a woman, pockmarked from the plague but relatively fresh.  \n\nOn the hand is a ring.  Removing the ring and inspecting it reveals an engraving:\n\n\"For Deliah\"", progress = "{name}.  You return, so I assume your investigations bore fruit?", completion = "You say that this ring was worn by a woman, recently killed?\n\nThe only nearby source of such a body would be the mass graves in Tirisfal.  The Rot Hide Gnolls must be taking those corpses to Fenris Isle!", objectives = "Bring Deliah's Ring to High Executor Hadrec at the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[440] = { id = 440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Engraved Ring", description = "If you want to find the husband or beloved who gave Deliah her ring... then speak with Magistrate Sevren in Brill.  He should have records of recent deaths and, with luck, can discover who Deliah is.\n\nBut I wouldn't hope.  Whoever gave her the ring is probably dead.  Or if he's undead he probably no longer cares about Deliah.", progress = "Hello, {name}.  What brings you back to Brill?", completion = "A Deliah did live in Brill not long ago.  She was buried in the mass grave but if what you say is true, then the Rot Hide Gnolls must have stolen her body and taken it to Silverpine.\n\nThe Rot Hides, like all the Scourge, must be destroyed.  I trust you are taking steps to make that happen.", objectives = "Bring Deliah's Ring to Magistrate Sevren in Brill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[441] = { id = 441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raleigh and the Undercity", description = "Deliah had a husband, Raleigh, who now dwells in the Undercity.  If the Deliah who lived in Brill is the one who owned this ring, then Raleigh will know.\n\nRaleigh is in the Trade Quarter of the Undercity.", progress = "Do I know you?", completion = "Yes, this ring was my wife's.  Her fate was the fate of all who fail to endure these harsh times.  I feel nothing for her death, nor for the story you tell of her body's abduction.\n\nSuch feelings have long since grown cold within me.  But desire does still burn in my dead heart, {name}.\n\nDesire for revenge.", objectives = "Bring Deliah's Ring to Raleigh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[442] = { id = 442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Fenris Isle", description = "Now is the time to assault the Scourge's place of strength in Silverpine: Fenris Isle.\n\nYou must again go to the Isle and destroy Thule Ravenclaw.  I want his head!\n\nThis mission is as dangerous as it is vital, {name}.  You must not fail.", progress = "The Scourge cannot be allowed to remain in Silverpine, {name}.  Come back to me when you have proof of Thule's death.", completion = "The death of Thule Ravenclaw was no small event, {name}.  Renferrel tells me that the energies released when you destroyed Thule were felt even as far as the Sepulcher.\n\nYour actions ring through the ranks of the Forsaken.  Your value to us grows.", objectives = "Bring Thule's Head to High Executor Hadrec at the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[443] = { id = 443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rot Hide Ichor", description = "Before we launch an assault on Fenris Isle, we must determine who is behind the rot hide gnolls.  Our apothecaries believe their origin lies within the strange fluid that flows through their bodies.\n\nGo to Fenris Isle, east of the Decrepit Ferry, and collect rot hide ichor from the gnolls you find there.  Bring it to Apothecary Renferrel, stationed outside the Sepulcher.", progress = "Do you have the rot hide ichor, {name}?", completion = "Very good.  This ichor will help us understand the nature of the rot hides, and may show us their weakness...\n\n...if they have one.", objectives = "Bring 8 bottles of rot hide ichor to Apothecary Renferrel at the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[444] = { id = 444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rot Hide Origins", description = "I have reduced the ichor you brought me and separated it into its base components.  My findings are not conclusive, but I have determined that warlock and necromantic magics were used in the ichor's creation.\n\nWhile I continue to study the ichor, I want you to take a sample to Bethor Iceshard in the Undercity.  Bethor is not an apothecary, but his knowledge of magic may help to unravel the mystery of the rot hides.\n\nGo.  You will find Bethor in the Magic Quarter of the Undercity.", progress = "My studies require great concentration.  So I hope your visit is not a frivolous one.", completion = "This substance is laced with powerful spells, some of which I have not seen for a long, long time...\n\nOne moment -- I must invoke a spell of divination...", objectives = "Bring the Sample Ichor to Bethor Iceshard in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[445] = { id = 445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery to Silverpine Forest", description = "Time is a luxury that is not afforded to those of us under the employ of Lady Sylvanas.  Surely you know this by now.\n\nAs a member of the Royal Apothecary Society it is my duty to share my knowledge with my colleagues so that our collective efforts might one day provide The Dark Lady with the New Plague she so badly desires.\n\nTake these findings to Apothecary Renferrel who is stationed at The Sepulcher in Silverpine Forest.  Follow the roads to the south from Brill.  From the Undercity go southwest.", progress = "What business do you have with me, {class}?", completion = "Ah, how good of Apothecary Johaan to send his research.  With so many new developments here in Silverpine, I nearly forgot about the findings coming out of Lordaeron and Tirisfal Glades.  Which reminds me, I need to get those samples off to the Necropolis soon.\n\nBut you must excuse my rambling.  Extend your stay in Silverpine, {name}.  We could use an able bodied {class} like you around here.", objectives = "Take Apothecary Johaan's findings to Apothecary Renferrel in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[446] = { id = 446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thule Ravenclaw", description = "This Ichor was crafted by an old colleague of mine: Thule Ravenclaw.  He was a young, promising mage before the great war, but when the Lich King rose to power, he betrayed his brethren and allied with the Scourge.\n\nI did not realize he still lives, nor that he leads the Rot Hides in their forays against us!\n\nI know many of his spells, and can help concoct a potion to counter them.  Take this scroll back to Apothecary Renferrel.  It has the incantations needed for the potion.", progress = "Greetings, {name}.  What did Bethor have to say?", completion = "This scroll is laced with powerful magic.  I've never used such forces in a potion ... it will be a powerful mixture, and should serve you well should you attack Thule in his stronghold on Fenris Isle.", objectives = "Bring Bethor's Scroll to Apothecary Renferrel at the Silverpine Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[447] = { id = 447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Recipe For Death", description = "Arthas's numbers are overwhelming. But with a New Plague we could eradicate both the Scourge Army and the Human infestation once and for all.\n\nMy studies have proven that spider blood combined with a toxin derived from a grizzled bear heart results in a deadly elixir. Collect samples from the spiders in the Skittering Dark to the northwest and from the bears wandering throughout Silverpine Forest. Deliver the reagents to Master Apothecary Faranell of the Royal Apothecary Society in the Undercity.", progress = "Hail, {class}.  What business do you have with the Royal Apothecary Society?", completion = "How good of Apothecary Renferrel to send you to me, {name}.  These samples will indeed prove useful to the cause.  I will begin studying their toxic and contaminable properties at once.", objectives = "Collect 6 Grizzled Bear Hearts and 6 samples of Skittering Blood and deliver them to Master Apothecary Faranell in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[448] = { id = 448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Hadrec", description = "Before you launch an assault on Fenris Isle, report to High Executor Hadrec.  He may have additional information or equipment you'll need.", completion = "If what Bethor says is true then Thule Ravenclaw is a force that must be dealt with, and dealt with soon.\n\nTo aid in this task, you may take something from our arsenal here...", objectives = "Report to High Executor Hadrec at the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[449] = { id = 449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deathstalkers' Report", description = "Although Quinn's wounds are mending, I want to get our report to High Executor Hadrec as quickly as possible.  It has information that is vital to the Forsaken's occupation of Silverpine.", progress = "Did you discover the fate of the Deathstalkers?", completion = "I hadn't accounted for the level of Scourge presence we've seen in Silverpine Forest, nor for the troubles our Deathstalkers have had in their scouting efforts.\n\nYour aid to our Deathstalkers was invaluable, {name}.  And you will be commended.", objectives = "Bring the Deathstalker Report to High Executor Hadrec at the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[450] = { id = 450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Recipe For Death", description = "You can be of further service to the Royal Apothecary Society, {name}.\n\nWhen Arugal cast his wretched magic on the forest, he cursed one of our most promising members, Apothecary Berard.  Now a mindless servant of Arugal, Berard is useless to us.  But his findings might prove to be of worth.  He was studying an ancient plague that killed off all the aquatic life in Lake Lordamere ages ago.\n\nRetrieve Berard's Journal from his study in the Pyrewood Village Inn and take it to Apothecary Renferrel.", progress = "I see you are back, {name}.", completion = "Apothecary Berard's journal!  Why you are quite brave, {name}.  Now let's see what Berard was up to before he went mad. . .", objectives = "Retrieve Apothecary Berard's journal from Pyrewood Village and take it to Apothecary Renferrel at the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[451] = { id = 451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Recipe For Death", description = "According to Berard's Journal the moss from Lake Skulkers and Creepers might prove useful for our quest to brew a new plague.  Those beasts dwell on the islands in Lake Lordamere to the east.\n\nHe also mentions a very rare Hardened Tumor that he discovered on a Vile Fin murloc.  Apparently the tumor is so rare Berard was only able to obtain one.\n\nCollect samples of the moss as well as the rare Hardened Tumor and take them to Master Apothecary Faranell in the Undercity.", progress = "What brings you back to the Undercity, {name}?", completion = "Such a blow to the Royal Apothecary Society to lose Berard.  But through your hard work and Apothecary Renferrel's diligent research Berard's studies will still be useful to The Dark Lady's plight.\n\nWe are on the cusp of something great here, {name}.  If you were not so skilled in the ways of combat I would try to recruit you for membership in the Society.", objectives = "Bring 6 samples of Lake Creeper Moss, 6 samples of Lake Skulker Moss and a Hardened Tumor to Master Apothecary Faranell in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[452] = { id = 452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pyrewood Ambush", description = "You got here just in the nick of time, {name}!\n\nThe Pyrewood Council will be returning any moment.  Arugal has other matters to tend to in the keep.  He uses the Council as mere puppets to keep the mindless minions of Pyrewood under his control.  But I believe that without the guidance of the Pyrewood Council, the sons of Arugal will turn against their master.\n\nI cannot handle them all by myself.  I need you to help me.  Together we can lay waste to the Council for Lady Sylvanas.", completion = "You fought like a true disciple of the Dark Lady, {name}.  With the council dead, perhaps we can gain control of this town once and for all and drive Arugal from Shadowfang Keep.  I salute you!", objectives = "Help Deathstalker Faerleia kill the Pyrewood Council.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[453] = { id = 453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding the Shadowy Figure", description = "Good luck, {name}.  I hope you find the chap, and I hope you find him alive.\n\nIf he's left the safety of Darkshire then he could be prey to the beasts of the wilds.", progress = "Who are you??  Leave me be!", completion = "<Jitters sighs...>\n\nYes, I'm the author of that book.  You finally found me, eh?\n\nWell if you read that journal...then you only know the half of it!", objectives = "Find the Shadowy Figure. Your clues:\n\nHe is not native to Darkshire.\n\nHe is a nervous, jittery person.\n\nHe left Darkshire and headed west.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[454] = { id = 454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "After the Ambush", description = "We'd been hauling the barrels of powder back and forth in trips before this... business. Now we have to split up the work, Miran's taking the barrels and I'm watching over the other ones.\n\nI don't feel safe letting Miran haul the rest of the shipment by himself. When he's ready to go, maybe you could escort him on his next trip?", completion = "Hello, {class}.\n\nYou'll be escorting me to the excavation site? That's good to hear... After Saean and his cronies, who knows what else the Dark Irons might have up their sleeves?\n\nAnyways, let me just make some final checks. Talk to me again when you're ready to go.", objectives = "Speak with Miran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[455] = { id = 455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Algaz Gauntlet", description = "Orcs of the Dragonmaw clan have a haven in the Wetlands.  And now they have expanded into Dun Algaz!  We can't let them keep their foothold here or Loch Modan will be cut off from Menethil Harbor, our port and stronghold in the Wetlands.\n\nBreak through Dun Algaz to the Wetlands beyond, and kill some orcs for good measure!  Report to Valstag Ironjaw in Menethil Harbor.\n\nMenethil is through Dun Algaz, then north along the road, then west at the fork.\n\nWe're counting on you, {name}.  Do not fail.", completion = "Your report is full of bad news!\n\nI see the Dragonmaws are making a strong move into Algaz.  Normally the Dragonmaws just hide up in the hills.  What made them surge into Algaz is still a mystery...\n\nThank you, {name}.  And we'll probably want your help dealing with these orcs.", objectives = "Traverse Dun Algaz.\n\nKill 8 Dragonmaw Scouts and 6 Dragonmaw Grunts.\n\nReport to Valstag Ironjaw in Menethil Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[456] = { id = 456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Balance of Nature", description = "Greetings, {name}.  I am Conservator Ilthalaine.  My purpose in Shadowglen is to ensure that the balance of nature is maintained.\n\nThe spring rains were particularly heavy this year, causing some of the forest's beasts to flourish while others suffered.\n\nUnfortunately, the nightsaber and thistle boar populations grew too large.  Shadowglen can only produce so much food for the beasts.  Journey forth, young {class}, and thin the boar and saber populations so that nature's harmony will be preserved.", progress = "There is still work to be done, {name}.  Return to me once you have thinned the nightsaber and thistle boar populations.", completion = "You performed your duties well, {name}.", objectives = "Kill 7 Young Nightsabers and 4 Young Thistle Boars and return to Conservator Ilthalaine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[457] = { id = 457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Balance of Nature", description = "Thinning the younger population of creatures here in Shadowglen was a good start, {name}, but there is still work to be done.\n\nThe resources of the forest will be depleted too quickly if the problem is not addressed.  Killing nature's beasts is a necessary evil for the good of all who share the land.  Venture into the forest and slay mangy nightsabers and thistle boars in the name of balance.", progress = "Your task is not yet complete, {name}.  Return to me once 8 mangy nightsabers and 8 thistle boars have been killed.", completion = "You have proven your dedication to nature well, {name}.  A young {class} like yourself has a promising future.", objectives = "Conservator Ilthalaine needs you to kill 7 Mangy Nightsabers and 7 Thistle Boars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[458] = { id = 458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Woodland Protector", description = "Thank goodness you are here, {class}. Strange news has traveled to me through the whisperings of the forest spirits.\n\nThe mysterious woodland protector, Tarindrella, has returned to Shadowglen. The dryad's presence has not been felt in the forests of Kalimdor in years. Something is surely amiss if she has journeyed back to this land.\n\nSeek out Tarindrella and see what business she tends to in our grove. One of the Sentinels reported seeing her to the southwest of Aldrassil.", completion = "I see you found me, young {race}.  Melithar is a wise druid to have sent you.", objectives = "Seek out the dryad known as Tarindrella.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[459] = { id = 459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Woodland Protector", description = "Something evil is brewing in the forests of Teldrassil.  Look long the hills to where the peaceful furbolgs used to dwell.  They have deserted their homes and are amassing under the name of the Gnarlpine tribe.\n\nOnly the corruption of wicked Fel Moss could cause such a transformation.  The grells and grellkin have infested the area and are threatening the residents of Shadowglen.  \n\nEngage these grells and grellkin, {name}, and see if they are indeed caught under the enchantment of the wicked Fel Moss.", progress = "Satisfy my suspicions, {name}.  Bring to me 8 Fel Moss.", completion = "Your service to the creatures of Shadowglen is worthy of reward, {name}.\n\nYou confirmed my fears, however.  If the grells have become tainted by the Fel Moss, one can only imagine what has become of the Gnarlpine tribe of furbolgs who once lived here.\n\nShould you find yourself in Dolanaar, able {class}, seek out the knowledgeable druid, Athridas Bearmantle.  He shares our concern for the well being of the forest.", objectives = "Collect 8 Fel Moss and bring them to Tarindrella.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[460] = { id = 460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resting in Pieces", description = "You don't look like a rot hide.  Good.  I had lost hope...\n\nMy name is Alaric, and I was once Thule's head servant and bodyguard.  He used his magic to \"protect\" me from the Plague of Undeath, but instead his spell gave me an unlife from which I cannot escape.  And after creating the cursed rot hide gnolls, Thule beheaded me... and gave my head to the gnolls as a plaything!\n\nPlease, take me to my body.  I believe the gnolls buried it here in Fenris Keep, near the stable, in an unmarked grave.", progress = "This grave was hastily dug.", completion = "Thank you, {name}.  I had feared the Gnolls destroyed my body.  It is good to know they did not.", objectives = "Bring Alaric's Head to his grave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[461] = { id = 461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hidden Niche", description = "I know of a hidden niche within the keep that holds an item dear to Thule, and his old colleagues.  It also holds something you might find useful.  Take me there!\n\nThe alcove is in the southwestern tower of the keep, behind a dusty shelf.\n\nTake my body, but leave my boots.  They never fit me anyway...", progress = "This is the spot!  Bring me closer...", completion = "There we are, it's open.  Leave me here.  I spent the best days of my life in this keep, and the thought of resting within its walls gives me comfort.\n\nBe sure to close the alcove tight - I don't want those Rot Hides to find me.\n\nOh, and take this.  You've earned it.", objectives = "Take Alaric to the hidden alcove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[463] = { id = 463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Greenwarden", description = "You've heard of the Greenwarden?  You're not looking for him, are you?  Well I say you're crazy if you are, but who am I to keep a fool from <his/her> death?\n\nIf you are seeking that beast, then I hear he is in the marsh, east of the road where it forks to Dun Modr.  He's lurking there among the crocs...and worse!\n\nAnd leave your money here.  You won't need it where you're going...and you don't want to chip ol' Greenie's tooth on your gold when he bites you in half, do you?", completion = "The roots and ferns speak well of you, small one.  Although I have many names, I answer to only a few.  But you may call me Rethiel.\n\nAnd you must harken...for these lands weep from festered wounds, and I would charge you to heal them.", objectives = "Find the Greenwarden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[464] = { id = 464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Banners", description = "The Dragonmaw orc clan was all but destroyed by the end of the Second War, after they lost control of their red dragon pets.  The dragons were not very happy with their old masters, and fiercely hunted the Dragonmaws.  What few remained fled from Grim Batol and into the Mountains east of Whelgar's Excavation.\n\nNow they've gained strength, and have an encampment northeast of Menethil.\n\nWe want you to attack that encampment.  Gather and bring me their war banners as proof.", progress = "Have you attacked the Dragonmaw encampment?", completion = "Well fought, {name}.  The Dragonmaws are not the same threat they were when they had dragons, but they're still fierce opponents.\n\nThe Dragonmaws are led by Nek'rosh, son of Nekros, who was the former head of the Dragonmaws years ago.  Nekros used powerful magic to tame the Red Dragons, but when that magic failed him...the dragons were not happy.\n\nNekros was killed, and his son has vowed revenge against the dragons who slew his father.", objectives = "Bring 8 Dragonmaw War Banners to Captain Stoutfist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[465] = { id = 465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nek'rosh's Gambit", description = "While you were fighting the Dragonmaws, we discovered more of their plans.\n\nNek'rosh has built catapults and aims to lay siege to Menethil!  And with the fighting in Dun Algaz, we're effectively blocked from reinforcements!\n\nYou need to take out those catapults.  They're in the Dragonmaw encampment.\n\nHere, take this tinder.  Fight your way to the catapults and light them with the tinder.\n\nAnd after you've done that, find and kill Nek'rosh.  We need to cut this Dragonmaw beast down...at its neck.", progress = "The first catapult is before you.  Will you set it aflame?", completion = "You place some of the tinder on the catapult then strike a spark onto it.\n\nFlame erupts and quickly spreads!", objectives = "Destroy the Dragonmaw catapults.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[466] = { id = 466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Search for Incendicite", description = "I heard that a rare ore, incendicite, was found in the Wetlands, in a cave northwest of Algaz Gate.  Incendicite is volatile stuff and hard to use without blowing yourself up, but I'm sure if it's smelted the right way it could make cannon shells that pack a mighty punch!\n\nGet me incendicite ore and I'll find someone brave enough to experiment with it.\n\nOh, and to extract that ore from a vein you'll need skill in mining.  If you don't have it, then ... bring a friend who does to that cave!", progress = "Where is that ore, {name}?!", completion = "You got the ore!  Well done, {name}!  I'll get someone to work with this right away.  Let's hope he doesn't blow himself up!", objectives = "Bring 6 loads of Incendicite Ore to Pilot Stonegear in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[467] = { id = 467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonegear's Search", description = "Pilot Stonegear loves his siege engine, as every pilot should!  And he's always eager to find new ways to improve his tank's firepower!\n\nHe heard rumors of a rare ore and is looking for someone to hunt it down for him.  If your boots are starting to itch, then find Stonegear at Steelgrill's Depot in Dun Morogh and see what he wants.", completion = "Hello {name}.  You're here about the task I have, eh?  It's good to see a young {race} like yourself whose blood burns at the prospect of adventure!", objectives = "Speak with Pilot Stonegear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[468] = { id = 468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Mountaineer Rockgar", description = "Mountaineer Rockgar is looking for volunteers for a mission through Dun Algaz and into the Wetlands.  \n\nIf you want to get your boots wet in that soggy county to the north, then speak with Rockgar at Dun Algaz.  Dun Algaz is north up the road, beyond the guard tower.", completion = "Hello, {class}!  You're here for the scouting mission, are you?  Very good!\n\nI hope your gear is in good condition, because this \"scouting\" mission has changed into something more messy...", objectives = "Speak with Mountaineer Rockgar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[469] = { id = 469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Delivery", description = "Greetings, traveler!\n\nDon't suppose you might be heading in the direction of Menethil, would you? If you're not, I'd suggest you stop there, it's a good place to purchase goods and even have a pint and relax.\n\nNow, if it just so happens that you're heading in that direction, I don't suppose you'd mind taking this bundle of crocolisk skins to James Halloran, the tanner?\n\nI'd do it myself, but my wife's been in quite a mood lately, and I'd like to put off facing her as long as possible.", progress = "Hello there, {class}. Could I interest you in a pair of boots?  Perhaps some newly cured skins?", completion = "Hmm, this is from Einar, right? Hasn't delivered his skins to me in person for almost a week now. No doubt it's some differences with the wife!\n\nMaybe I'll have my wife go speak with Sida sometime...", objectives = "Deliver the Bundle of Crocolisk Skins to James Halloran, the tanner, in Menethil Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[470] = { id = 470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Digging Through the Ooze", description = "On my weekly visit to Ironbeard's Tomb I was attacked by dreadful, dripping oozes! Naturally, I panicked.\n\nI threw my bag at one, but it didn't do anything! The ooze just sucked it right up... Luckily, it did give me enough time to get away.\n\nThe bad news is that I really need to get the contents of my bag!\n\nI don't know which ooze I threw my bag at; they all looked the same! Ironbeard's Tomb is northeast of here, near Dun Modr. Thank you so much!", progress = "Did you find my bag?", completion = "Oh, thank you, {name}! I was afraid that it was lost for good!\n\n\n\nHm, I don't have much use for this anymore, but wash it off and I'm sure you could make use of it.", objectives = "One of the oozes at Ironbeard's Tomb has Sida's bag, retrieve it and bring it back to her in Menethil Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[471] = { id = 471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apprentice's Duties", description = "I sent my apprentice out into the marshes to skin some of our famous giant Wetlands crocolisks. When he didn't return, I went out to look for him... Let's just say it wasn't a pretty sight.\n\nMidwife says he might pull through, but in the meantime I still need my skins!\n\n...If you'd like to kill a few more of the brutes, I wouldn't be opposed, after what they did. You'll find the crocs north up the coast, beyond the murloc hovels.", progress = "My apprentice is like a son to me.  It's going to be hard for him to live his life with only one leg.\n\nAh, {name}, how goes it?  Do you have my skins?", completion = "Hmm... Don't suppose you'd be interested in becoming my apprentice, would you?\n\nHah! No, I'm just kidding. You're much too old, for one thing.  Besides - from the looks of you, it would seem that you have other ambitions in life.  Nonetheless, these are some fine skins you've procured, and I'll be able to put them to good use.", objectives = "Collect 6 Giant Crocolisk Skins and bring them to James Halloran in Menethil Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[472] = { id = 472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fall of Dun Modr", description = "Dun Modr has fallen to the Dark Iron Dwarves!\n\nMy wounds are grave, {class}.  Most of the regiment was killed!  The Dark Iron thugs attacked us before we could regroup from the Thandol Span ambush.\n\nOur leader, Longbraid, sounded the retreat horn.  As we left the town I was hit by a stray axe in the back.  All went black.\n\nI awoke here in Menethil but I fear for my fellow soldiers.  Hope still burns within me.  Perhaps Longbraid is still alive!  See if you can find him near Dun Modr, {race}!", completion = "What brave {class} sends word from Menethil?  Ah {name}, they call you.\n\nYou bring hope to a hopeless situation.  'Tis good news indeed that young Harlo survived.  While fleeing he received a grievous wound.  We had but little time to send him on his way on the back of the only surviving steed with the regiment.\n\nBut now we face a perilous situation.  Dun Modr has fallen and we are but a shadow of the great regiment we once were.", objectives = "Search for Longbraid near the town of Dun Modr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[473] = { id = 473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Captain Stoutfist", description = "{name}.  The Dragonmaw orc clan is showing its strength in more than just Algaz.  Captain Stoutfist has asked to speak with those willing to offer aid against these orcs.  He is inside the keep, in the war room.", completion = "{name}.  Valstag briefed me on your past success with the Dragonmaw Orcs at Dun Algaz.  You're a {race} of worth.\n\nAnd I have a task for you.", objectives = "Speak with Captain Stoutfist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[474] = { id = 474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defeat Nek'rosh", description = "Now that the catapults have been burned, find and kill Chieftain Nek'rosh.", progress = "Have you killed Nek'rosh?", completion = "Stoutly done, {name}.  You have dealt a telling blow to the Dragonmaw orc clan.  They may never recover.  And the destruction of those catapults has made Menethil Harbor safe.\n\nYou are a {race} of merit, and the kingdom of Ironforge rewards those who serve it well.", objectives = "Kill Chieftain Nek'rosh\n\nBring Nek'rosh's Head to Captain Stoutfist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[475] = { id = 475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Troubling Breeze", description = "A troubling breeze blows through the forest.\n\nGaerolas Talvethren serves as Great Warden to the hibernating Druids of the Talon in the Ban'ethil Barrow Den.  His duty as the chosen protector of the Sleeping is to ensure their safety so that their pact with Ysera remains fulfilled.\n\nBut word from Gaerolas is now delayed and I grow nervous.  Travel east to Starbreeze Village and bring back a report from Gaerolas so that I can put my worries to rest, knowing my dreaming brethren slumber safely.", completion = "Thank the forest spirits you are here!  I knew Athridas would sense trouble and send help.", objectives = "Seek out Gaerolas Talvethren in Starbreeze Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[476] = { id = 476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnarlpine Corruption", description = "The Gnarlpine tribe has been corrupted!\n\nThe once peaceful furbolgs have turned against the protectors of the forest.  They ambushed me as I left for the Ban'ethil Barrow Den and proceeded to pillage Starbreeze Village.  Ursal the Mauler, their chieftain, is using the evil powers of the Fel Moss to drive them mad.\n\nI am too wounded to return to Athridas to bring him this grave news.  The task is left to you, young {class}.  We can only hope that the deranged Gnarlpines have not made it to Ban'ethil yet!", completion = "By the stars!  This is quite disturbing indeed!", objectives = "Return to Athridas Bearmantle in Dolanaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[477] = { id = 477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Border Crossings", description = "As you may know, the town of Ambermill remains a source of human opposition, mainly through the support they receive from the wizards of Dalaran.\n\nI don't know what their plan is, but for them to show interest in a backwater village like Ambermill indicates that it must have some greater importance.\n\nThey've been shipping crates by the wagon from Hillsbrad. Many of those supplies end up at a small camp north of Pyrewood Village. Retrieve the contents of a crate and return them to me.", completion = "<Prying open the lid of the crate, you find an assortment of carefully-packed objects. On the top of the crate lies a bundle of maps, yellowing with age, that appear to depict Silverpine Forest and other parts of western Lordaeron.\n\nUnderneath the maps is a mysterious-looking magical pendant.>", objectives = "Retrieve the contents of one of the Dalaran wizards' crates. You will find Pyrewood Village to the south.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[478] = { id = 478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maps and Runes", description = "<You quickly remove the pendant from the crate and replace the lid.>", progress = "Have you learned anything useful, {name}?", completion = "Maps and this... pendant, hm? Interesting.\n\nIt is obvious that the Dalaran wizards are interested in Ambermill for some purpose, but still, their aim is hidden to me.\n\nPerhaps Dalar will know something of their use.", objectives = "Bring the strange pendant to Shadow Priest Allister at the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[479] = { id = 479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambermill Investigations", description = "Dalar is attempting to locate the source of the wizards' spellcasting. For now, we'll have to slow their progress in any way we can...\n\nThe conjurers, mages and protectors are no doubt carrying the pendants. Remove and retrieve them.\n\nTake the main road south and the eastern fork into Ambermill.", progress = "We must hurry, their plans must not come to fruition, or we may lose our hold on Silverpine Forest.", completion = "Dalar has found that the weaving is quite far along, despite the setback.\n\nA wizard of great power is guiding the magic energy. He must be stopped quickly.", objectives = "Obtain 8 Dalaran Pendants for Shadow Priest Allister at the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[480] = { id = 480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Weaver", description = "An archmage of great power is overseeing the reactivation of the ley energy node. With the progress they have made, our only hope of stopping them is by killing him. It will be difficult, he is no doubt protected by many other mages and warders.\n\nYou must go, and you must dispatch him quickly. When he is dead, retrieve his staff for me. Go now.", progress = "Quickly, time runs short, {name}!", completion = "The magic of the wizards dissipates, and the ley energies fade into dormancy. Your efforts have been fruitful, {name}, and we have dealt a major blow to our enemies, and to the overbearing wizards of Dalaran.\n\nWe must be vigilant, however, knowing that source of energy lies so close at hand... Plans must be made for the future.", objectives = "Kill the Dalaran archmage, then retrieve his staff for Shadow Priest Allister at the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[481] = { id = 481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalar's Analysis", description = "Take the pendant to Dalar Dawnweaver, perhaps he can shed some light on the wizards' plans.", progress = "Yes, {class}? What is it?", completion = "Interesting, more machinations of the Kirin Tor, it would seem. This is a powerful artifact. It was used frequently by powerful wizards of the Kirin Tor to channel magical energies.\n\nThat they are delivering so many to Ambermill indicates that they must be undergoing a project of some magnitude.\n\nI will see if I can pierce their shields and ascertain their intent.", objectives = "Take the rune-inscribed pendant to Dalar Dawnweaver at the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[482] = { id = 482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalaran's Intentions", description = "Of course! How could I have forgotten?\n\nAmbermill was one of the sites earmarked by the Kirin Tor, noted because it houses a dormant ley energy node. The wizards must be planning to reactivate the node and use its energies for some greater purpose.\n\nWe cannot allow this to happen...\n\nIt will take a great amount of power to activate the area's ley energies, we can stall them by taking the pendants away from the wizards.\n\nRelay this information to Allister, he will decide a course of action.", completion = "Ill news you bring, {name}. If Dalar is correct--and I've no reason to believe he isn't--we must move quickly.\n\nI must confer with him on our plan of attack. But in the meanwhile we will have to delay their progress.", objectives = "Speak with Shadow Priest Allister at the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[483] = { id = 483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Relics of Wakening", description = "Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den to the west.\n\nThe slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help. The delicate hibernation ritual cannot be broken without the Relics of Wakening.\n\nJourney to the Den and retrieve the Raven Claw Talisman, Black Feather Quill, Sapphire of Sky, and Rune of Nesting. The druids store them in sacred chests.  Return them to me and I will prepare the awakening ritual.", progress = "{name}, the kidnapped Druids of the Talon will be forever trapped in the Emerald Dream if we cannot retrieve the Relics of Wakening from the Ban'ethil Barrow Den to the west.\n\nFor every minute we delay their fate comes one step closer to eternal doom.", completion = "You have succeeded, young {class}!  Well done.  And just in time I might add.", objectives = "Retrieve the Relics of Wakening and bring them to Athridas Bearmantle in Dolanaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[484] = { id = 484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Young Crocolisk Skins", description = "I'm James Halloran, the tanner. My cured crocolisk skins are sought after all over, shipments leaving by boat to ports around the world.\n\nMet Einar? He's one of the hunters that brings crocolisk skins in for me.\n\nI'm a bit short on the softer skins that come off crocolisk young.\n\nBeing that I'm running low, I'll pay you top coin for a stack of the skins. You can find the young crocs in the marshes right outside of town.", progress = "{name}, right? Do you have my skins?", completion = "Nice work you've done here, {name}. The quality of these skins is superb. I'll have to get them into the curing process as soon as possible. Oh, but before I get to that, there's some other work I need done that I think you might be able to take care of.", objectives = "Obtain 4 Young Crocolisk Skins for James Halloran in Menethil Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[485] = { id = 485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find OOX-09/HL!", description = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"My name's Oglethorpe Obnoticus, and my homing robot has crashed!  I will reward you for its recovery; please take this beacon to the robot!\"\n\n\"I now have computed the coordinates of the robot for you; it crashed at the head of the river near Skulk Rock!\"", progress = "You appear to have uncovered the wreckage of... a robotic chicken?  The voice from within the egg crackles to life again:\n\n\"Yes, excellent work!  This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs.  Go ahead and place the beacon inside the rover - the beacon will take care of the rest!\"", completion = "You place the egg... distress beacon... inside the chicken... homing robot.\n\nHums and whirs are heard from inside the robot as it struggles to stand up.  After the robot comes to life, Oglethorpe's voice is heard once more, but now from inside the robot:\n\n\"OOX-09/HL is working at least, but it needs major repairs!  It is much too heavy for you to carry it... but I think I have an idea.  Are you up for watching over it some more?\"", objectives = "Take the distress beacon to Oglethorpe's homing robot at the head of the river in the Hinterlands, near Skulk Rock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[486] = { id = 486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursal the Mauler", description = "Now the time has come to save the Druids of the Talon. If we fail now, {name}, they will be forever lost in sleep.\n\nI shall prepare the Relics of Wakening and perform the ritual. For my work to take effect, the cursed beast responsible for this horrible situation must be slain.  Only then will the ritual be complete.\n\nIt was Ursal the Mauler who meddled with our brethren's calling and it is Ursal the Mauler who must now pay so they can be freed.  Travel to Gnarlpine Hold in the southwest and slay him.", progress = "Our brethren cannot be awakened until Ursal the Mauler has been slain, {name}.", completion = "{name} you have proven yourself a most worthy and able {class}.  A {race} who follows the path of honor as sure as you do is certain to find great glory in this world.\n\nMay the forest spirits protect you wherever your travels may take you.", objectives = "Kill Ursal the Mauler and return to Athridas Bearmantle in Dolanaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[487] = { id = 487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road to Darnassus", description = "The road to Darnassus must be kept safe.  Travelers heading from Dolanaar to Darnassus have been reporting ruthless attacks by corrupted furbolgs from the Gnarlpine tribe.\n\nImportant news and commerce travels to and from Darnassus by way of this road daily.  We cannot afford to have a rogue band of heathens terrorizing people.\n\nTake up arms in the name of the sacred forest, {class}.  Their den lies somewhere below this vantage point.  Slay 6 of these Gnarlpine ambushers and report back to me.", progress = "The road is still not safe, {class}. Travel forth and slay 6 Gnarlpine Ambushers and return to me.", completion = "You have served the good people of Dolanaar and Darnassus well, brave {class}.  As a member of the Sentinel force of Teldrassil I salute your efforts.", objectives = "Slay 6 Gnarlpine Ambushers and return to Sentinel Amara Nightwalker outside of Dolanaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[488] = { id = 488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zenn's Bidding", description = "Eager for work, I see.  Lucky for you a day never goes by that I don't wish I had a fledgling {class} to perform my bidding.\n\nYou see, {name}, I can make you very happy and provide you with things you never dreamed of having.  But in order for that to happen you must bring me certain items.\n\nMy business in the forest often requires certain. . .reagents.  Fetch for me 3 Nightsaber Fangs, 3 Strigid Owl Feathers and 3 swatches of Webwood Spider Silk.\n\nLet's keep this our little secret, {race}.", progress = "Have you been a busy little bee, {name}?  I've been waiting for you to bring me what I need.", completion = "Ha ha!  Well, done indeed.\n\nWho would have ever guessed that I, Zenn Foulhoof, would have a {race} to do my bidding?  Certainly not me!  But so it goes... this beloved world of ours is full of surprises.\n\nThree cheers for the naive and gullible!", objectives = "Bring Zenn Foulhoof outside of Dolanaar 3 Nightsaber Fangs, 3 Strigid Owl Feathers and 3 swatches of Webwood Spider Silk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[489] = { id = 489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Redemption!", description = "The Council of the Forest has news that you aided Zenn Foulhoof. The satyr is an enemy of the forest. As a {race}, you should know better than to defile the forest by killing Nature's creatures.\n\nYou must redeem yourself in the eyes of the Council if you wish to remain a friend of Teldrassil.\n\nTeach Foulhoof a lesson and you shall be redeemed. Fel Cones are corrupted seeds that fall from the trees. They billow with green smoke.\n\nGive some to Foulhoof. He'll think you have brought him a harmless snack.", progress = "What do you have for me, {name}?  A lovely snack I presume?", completion = "Ah, what a sweet {race}!  I knew you would come in handy!", objectives = "Collect 3 Fel Cones and give them to Zenn Foulhoof outside of Dolanaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[491] = { id = 491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wand to Bethor", description = "Thule once told me that, long ago, he and two colleagues created a magic wand, woven together from the apprentice wands each mage possessed.  This wand was a symbol of their friendship, and although Thule came to despise it he could not part with it, nor could he let the others have it.  So he stole the wand, and hid it in Fenris Keep.\n\nHere.  Take the wand to Bethor Iceshard, one of Thule's friends from years past.  I'm sure he will want it.", progress = "{name}.  Have you defeated Thule Ravenclaw?", completion = "...what is this?  Thule had our Woven Wand?  I thought it was lost when our friendship sundered and he sided with the Lich King!\n\nHe must not have invoked its power, for if he had I would have sensed it.  And it is good that he did not use it...\n\nThis is a marvelous find.  You have my gratitude, {name}, and will be rewarded.", objectives = "Take the Woven Wand to Bethor Iceshard in the Magic Quarter of the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[492] = { id = 492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Plague", description = "According to the Deathguard, another one of those foolish Dwarven Mountaineers has just been captured.  The Deathguard likes to use the cellar of the Gallows End Tavern as a holding cell until prisoners can be \"properly\" dealt with.\n\nWhy don't you go see how the Captured Mountaineer enjoys this special drink I made for him?  It contains a subtle hint of what The Dark Lady has planned for the rest of Azeroth.", progress = "Why if I had my trusted rifle you'd be as good as dead, {class}.  Just wait until the Steam Tank Brigade arrives to rescue me!", completion = "Ah, a drink at last.  I'm sure it's no Rhapsody Malt but I'll take anything to whet the old whistle at this point.", objectives = "Bring Johaan's Special Drink to the Captured Mountaineer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[493] = { id = 493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Hillsbrad Foothills", description = "The Royal Apothecary Society is under extreme pressure from the Dark Lady to develop a New Plague.  We are working diligently and have made much progress.  It is our belief that the success will be achieved much faster if we share information amongst the Society.\n\nFor that reason I want you to deliver my latest findings to Apothecary Lydon in Tarren Mill, a small town nestled in the Hillsbrad Foothills.  The journey will be a long one.\n\nHead south and stick to the roads.  Follow the signs closely!", progress = "You have something for me?", completion = "Ah, most excellent.  Apothecary Renferrel has my utmost respect.  I am anxious to study his work.", objectives = "Deliver Apothecary Renferrel's findings to Apothecary Lydon in the town of Tarren Mill in the Hillsbrad Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[494] = { id = 494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time To Strike", description = "Be silent and pay attention, {class}.\n\nI was sent to this position in order to survey the town of Hillsbrad.  My mission is one of reconnaissance.  It is imperative that you send word to High Executor Darthalia in Tarren Mill at once.  Let her know that I, Deathstalker Lesh, send the following message:\n\n\"The raven's cry from the west doth beckon.\"\n\nFollow the road to the east and pay close attention to the signs.  Now, hurry!  Off you go to Tarren Mill, and with urgency I might add!", completion = "The raven's cry from the west doth beckon?\n\nSuperb news!  Hillsbrad is ripe for attack.  We can carry out our plan of destruction now.  Varimathras will be pleased.", objectives = "Travel to Tarren Mill to deliver Deathstalker Lesh's message to High Executor Darthalia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[495] = { id = 495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crown of Will", description = "Mug'Thol and his ogre warband was sent to Alterac to retrieve the Crown of Will for Lady Sylvanas. Unfortunately, instead of returning it, the idiot decided to try it on... I suppose ogres can't resist anything bright and shiny.\n\nHis bumbling actions have become something of a problem, however. The Crown of Will enabled him to resist the possession placed upon him to serve Lady Sylvanas.\n\nThe Dark Lady wants an example made, travel to Tarren Mill in Hillsbrad and report to Melisara, my lieutenant.", completion = "You were sent by Shalindra? Very well then, you'll find I don't waste much time with idle chatter.\n\nMug'Thol is an irritant, and we will deal with him quickly, thoroughly, and without incident.", objectives = "Report to Melisara at Tarren Mill in the Hillsbrad Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[496] = { id = 496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixir of Suffering", description = "Ah, another wretched day in Tarren Mill.  All of this clean air puts me in such a foul mood, {name}.\n\nThe sooner we can plague the humans here, the better.  I've been conducting intense studies on possible killing agents to use in my concoctions but I haven't the time to collect them all.\n\nIf you want to make yourself of use, procure the following items for me:  10 Gray Bear Tongues and the very rare and hard to find, Creeper Ichor.  You'll find both bears and creepers just outside of Tarren Mill.", progress = "I see you are back.  I hope you were able to gather the agents I need.  Another deathless day will put me in such a gloomy mood.", completion = "These specimens are perfect.  Well, {name}, you have managed to bring me the slightest hint of joy on yet another miserable day.  Your efforts are appreciated.", objectives = "Apothecary Lydon of Tarren Mill wants 10 Gray Bear Tongues and some Creeper Ichor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[498] = { id = 498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rescue", description = "Me and some other warriors were sent by the Warchief to retrieve an object from Durnholde and to investigate this so-called Syndicate.\n\nWe went to Durnholde to take a look around, but we were taken by surprise by a large number of the humans. We fought bravely, but their sheer numbers were enough to defeat us. They took a few of us captive, but I was able to escape.\n\nDurnholde is just southeast of here, across the river. Drull and Tog'thar are being held there, you must go and rescue them.", progress = "You must make haste, {class}. I shudder to think what the humans might be doing to Drull and Tog'thar.", completion = "So the humans thought to turn our warriors into slaves, did they? We'll show them!\n\nIt would seem that they have taken Gol'dir, our leader, to another location. We must find him and rescue him. But we currently have no clue where he is...\n\nWhen we have a lead, I will be sure to tell you, {name}.", objectives = "Krusk in Tarren Mill needs you to free Drull and Tog'thar from Durnholde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[499] = { id = 499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixir of Suffering", description = "It will take but a moment for me to mix these components into what I have deemed an Elixir of Suffering.\n\nThere we go!  Ah, nothing brightens a gloomy day in these miserable foothills like bringing a little suffering into the world.\n\nLet us see if our little potion has achieved its desired effect.\n\nGive my assistant Umpi a taste of what the Dark Lady has planned for both humans and Scourge alike.", progress = "Ribbit!", completion = "Croak!", objectives = "Give Umpi the Elixir of Suffering.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[500] = { id = 500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushridge Bounty", description = "Crushridge ogres have dug an ogre mound up in the Alterac Mountains near the ruined city of Alterac.  And my scouts tell me they've taken over those ruins as well.\n\nWe can't let them get cozy up there; if they think they're safe where they are, then their next step will be to move down into the foothills, which will put them right at our front door!\n\nGo north to the Alterac Mountains and hunt ogres.  Bring me the Dirty Knucklebones they carry and you will earn a nice bounty.", progress = "{name}, are you still hunting ogres?  Do you have the knucklebones I had you gather?", completion = "Very good, {name}.  You must have hacked through a whole mess of ogres to get all these knucklebones.\n\nThat should keep them out of our hair.  At least, for a while.", objectives = "Gather 9 Dirty Knucklebones from Crushridge ogres in the Alterac Mountains. Bring them to Marshal Redpath in Southshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[501] = { id = 501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixir of Pain", description = "Oh, {name}. . .the flowers are blooming in Hillsbrad and the air is so fresh and brisk.  I can't help but to wallow in the misery of it all.  I look out my grimy window and long for the day when our New Plague brings this world the death it deserves.\n\nAs much as I would love to sit and brood all day, my duty to the Dark Lady calls.  Help me, would you?  My research leads me to believe I can make the most splendid death-brew with the blood of a Mountain Lion.  Bring some to me and we'll have a little fun.", progress = "I remember you, {name}.  You were going to help me out in concocting my latest elixir.  I'll need that blood before I can bring my own special brand of misery to the inhabitants of Hillsbrad.", completion = "Superb collecting, {name}.", objectives = "Bring 10 vials of Mountain Lion Blood to Apothecary Lydon in Tarren Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[502] = { id = 502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixir of Pain", description = "Ah, nothing like the smell of fresh blood in the foothills!\n\nNow we'll mix in a touch of this and a little of that and let the real fun begin!  What I have created with this blood, I like to call an Elixir of Pain.  If my calculations are correct this concoction could be the start of something very beautiful for Lady Sylvanas.  But what we need is a test.\n\nTake this elixir out to the northern farm in Hillsbrad Fields to the southwest.  Let's see how Farmer Ray's little dog Stanley likes this \"treat.\"", progress = "Woof?", completion = "You pour some of the elixir into your hand and hold it before Stanley's mouth.", objectives = "Feed the Elixir of Pain to Stanley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[503] = { id = 503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gol'dir", description = "From what I can tell of the documents you procured, Gol'dir is being held in a large Syndicate base to the north, most likely in the Alterac Mountains. He has been held captive far too long and must be freed.", progress = "Give me the key, {class}, I will undo the lock myself.", completion = "Thank you, {name}. I led the expedition from Durotar under the Warchief's orders, but as you can see, our plans went somewhat awry. They have held me captive here in this town, forcing me to work, hauling burdens, digging...\n\nWhat I have suffered is unimportant, however. There is important information you must deliver to whomever is leading our group now.", objectives = "Free Gol'dir then return to Krusk in Tarren Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[504] = { id = 504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushridge Warmongers", description = "Now that you've had a taste of the Crushridge ogres, I want you to really bloody their noses...\n\nGo into the Ruins of Alterac and seek out the Crushridge Warmongers.  I want you to cut down a good number of them - that's the only way those brutes will learn to keep their distance from Alliance territory.", progress = "You have more Warmongers to slay, {name}.  You should be up on the mountains on your task, not down here with your weapon stowed.", completion = "Very good.  Here is your reward.\n\nAnd when you were hunting those Warmongers, how did Alterac city look?  It's in bad shape I would guess.  Ogres are not known for their cleanliness.\n\nThankfully, your efforts will help keep them away from Southshore.", objectives = "Slay 15 Crushridge Warmongers, then return to Marshal Redpath in Southshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[505] = { id = 505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Syndicate Assassins", description = "I am the new magistrate of Southshore, recently assigned after the assassination of the previous magistrate.  The assassins were never found, but through our investigations we're almost certain they were hired by the Syndicate - a group of thieves led by villainous nobles of the now fallen kingdom of Alterac.\n\nThe Syndicate has a camp north of the Horde-occupied Tarren Mill, and our last clues led to that camp.  Slay the Syndicate members you find there.", completion = "Thank you, {name}.  Although they may still be lurking about, we hope that some of the thieves and footpads you slew were responsible for the last magistrate's death.  But even if they weren't, the Syndicate is a taint on this land and a stain on the human race.  \n\nTheir deaths are welcome to Southshore.", objectives = "Kill 12 Syndicate Footpads and 8 Syndicate Thieves, then return to Magistrate Henry Maleb in Southshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[506] = { id = 506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackmoore's Legacy", description = "A day or two ago, I was visited by the leader of this Syndicate. His name was Aliden Perenolde, and styled himself lord of this land. He confided in me his plans to take the orcs that stood against him as slaves, just as his father and his mentor, the despised Blackmoore, had planned.\n\nMore important was that he brought his mistress, a wisp of a girl named Elysa. Around her neck was the pendant the Warchief desires.\n\nNow go, I will make my own way, after I have settled my business here.", completion = "The nerve of those overbearing humans! We'll show them that the orcs shall never submit to their will!\n\nThis will now be our mission, in addition to recovering the trinket the Warchief desires. It would seem that by accomplishing one, we will also accomplish the other.", objectives = "Return the information gathered by Gol'dir to Krusk in Tarren Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[507] = { id = 507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Aliden Perenolde", description = "It is clear that Perenolde must be killed, his foulness removed from the world. His manor lies a ways to the north of here, on the shores of Lordamere Lake. Do your duty, {name}, then retrieve the pendant that the Warchief desires, and return here.", progress = "W-what do you want?", completion = "No, no please don't hurt me! I never meant your people any harm, he's had me against my will! Please... spare me!", objectives = "Kill Lord Aliden Perenolde and ask his mistress, Elysa, about Taretha's pendant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[508] = { id = 508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taretha's Gift", description = "The pendant? Of course you can have it... Take it! I want no memory of him... just please, please leave in peace...", progress = "You've returned, {name}. Success to report?", completion = "It is strange that the Warchief would expend so much over such a small thing. I do not claim to understand him, but I will follow him, whatever his commands. You did well, {name}, no doubt the Warchief will be glad to hear of your success.", objectives = "Return Taretha's pendant to Krusk in Tarren Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[509] = { id = 509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixir of Agony", description = "Another day, another elixir to be made. If it were up to me, I'd just let the pathetic humans and Scourge fight it out.  They seem bent on killing each other as is.\n\nAlas, our Dark Lady wants to help speed up the process a tad so why not pass these morbid days by spreading a little death and disease across the land?\n\nHere's the plan, {name}: you go out to Nethander Stead, south of Tarren Mill and east of the river and Southshore. Collect for me 6 Mudsnout Blossoms from the field for my next elixir.", progress = "Any luck at Nethander Stead?", completion = "Ah, the horrible reek of Mudsnout Blossoms.  At least those filthy Gnolls are good for something.", objectives = "Bring 6 Mudsnout Blossoms to Apothecary Lydon in Tarren Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[510] = { id = 510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foreboding Plans", description = "Among these documents is a list of requested supplies.  These include mundane items (food, weapons, clothing) as well as more exotic gear (masks, oil, poison).\n\nBut what is most notable is the urgency of the request - these supplies were needed soon in order to undertake what is described in the document as an \"important mission against Southshore.\"", progress = "{name}, you look anxious.  Is there something you wish to tell me?", completion = "<Maleb reads the documents.>\n\nThese are very troubling, {name}.  From the information in these documents, and from the Syndicate's actions in the past, we must assume that band of cutthroats has waged war on Southshore.", objectives = "Bring the Foreboding Plans to Magistrate Maleb in Southshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[511] = { id = 511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encrypted Letter", description = "One of the letters on this table is encrypted and inscrutable.", progress = "Yes, sir?  Do you have some business with me?", completion = "What is this?  Hold a moment...let me take a closer look.\n\n...\n\nHm, I have never before seen this form of encryption, but I must admit that my knowledge in that area is by no means complete.", objectives = "Bring the Encrypted Letter to Loremaster Dibbs in Southshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[512] = { id = 512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noble Deaths", description = "I fear the leadership behind the Syndicate is bent on Southshore's ruin.  We must strike hard at these leaders before their plans are realized.\n\nEnter the ruins of Strahnbrad, in the Alterac Mountains to the north.  We think the Syndicate is using the area as a headquarters.\n\nWe know this gang of cutthroats is run by former Alterac nobles.  They may be hiding as normal Syndicate agents, but you'll know you've killed a noble by the signet ring he wears.\n\nBring me those signet rings.", progress = "Have you been hunting the Syndicate?  Do you have those rings?", completion = "Stripping the Syndicate of its nobility will remove its ability to act decisively, and reduce it to nothing more than a gang of thugs.\n\nYou serve your Alliance well, {name}.", objectives = "Bring 7 Alterac Signet Rings to Magistrate Maleb in Southshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[513] = { id = 513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixir of Agony", description = "Just when I thought another day was going to pass devoid of any joy, you brought me those marvelous Mudsnout Blossoms.\n\nFirst I will mix them down into a fine composite.  We'll then need Master Apothecary Faranell in the Undercity to apply his colloid of decay to it and then we'll be ready for some good fun indeed!\n\nHere, take this Mudsnout Composite and run it off to Master Faranell at once, {name}.", progress = "Can you not see I am busy, {class}?  The Dark Lady insists on a new plague before the Scourge advance from Northrend overwhelms us.  And with the human threat pressing from the south, time becomes my most precious commodity.  This better be important!", completion = "Apothecary Lydon sent you?  Ah, why didn't you say so!\n\nDespite his gloomy disposition, Apothecary Lydon is one of our most dedicated and skilled members.\n\nThe good chap sends Mudsnout Composite!  I know what our friend in Hillsbrad is up to now.  And I like the way he thinks.  The Dark Lady would be most impressed with the progress he is making toward the new plague.", objectives = "Take the Mudsnout Composite to Master Apothecary Faranell in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[514] = { id = 514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letter to Stormpike", description = "I have a colleague in Ironforge who may be able to help decrypt this letter.  Go to the Library in the Hall of Explorers in Ironforge and speak with Prospector Stormpike.  Tell him I sent you and show him the letter.  If there's anyone north of Blackrock Spire who can read this, it is he.", progress = "Dibbs from Southshore sent you, did he?  How is the old bookworm doing?", completion = "Ah, encryption!  A specialty of mine.  Let me see here...", objectives = "Take the Cleverly Encrypted Letter to Prospector Stormpike in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[515] = { id = 515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixir of Agony", description = "A mudsnout composite?  Absolutely brilliant!  Why didn't I think of that?\n\nLet me contribute my colloid of decay to this devilish brew.\n\nIn order to activate the contaminating agents in this mudsnout mixture, Lydon is going to need a strong troll's blood potion, as well as some daggerspine scales and torn fin eyes from the southern coast of Hillsbrad.  He'll know what to do once you've gathered him all the reagents.  And my, how anxious I am to hear how his experiment goes!", progress = "So glad to see you back, {name}.  I was growing so terribly bored here.  Not a single entertaining thing to do besides poison and disease Umpi and reanimate her. . .over and over and over again.\n\nHow went the trip to the Undercity?  Were you fortunate enough to slaughter any humans along the way?", completion = "The excitement of this experiment has me feeling giddy!  You have been such a great help, {name}.  Together we will spread death and disease to this land!", objectives = "Bring the Mudsnout Mixture, a Strong Troll's Blood Potion, 5 Daggerspine Scales and 5 Torn Fin Eyes to Apothecary Lydon in Tarren Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[516] = { id = 516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beren's Peril", description = "I have received reports that a group of undead are holing up to prepare for an attack against us. Armed with this information, we can turn the tables and attack them first, nipping their little plan in the bud.\n\nUnfortunately, my information is spotty, at best. They are reported to be hiding in a location known as Beren's Peril. The exact location is unknown, but it appears to be a cave in the hills, near a pocket of Dalaran wizards.\n\nI trust your resourcefulness. Find them, and put them down.", completion = "If our scouts and agents continue to procure valuable information such as this, we shall have the Lich King's Scourge removed from our lands in no time.", objectives = "Locate Beren's Peril, then kill 6 Ravenclaw Drudgers and 6 Ravenclaw Guardians, then return to Shadow Priest Allister at the Sepulcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[517] = { id = 517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixir of Agony", description = "This new elixir is finally ready to be tested.  But why let a perfectly good, highly contagious plague go to waste on a mere frog or dog?  Let's have us some true fun in the name of Lady Sylvanas.\n\nHead down to Dun Garok.  You know the barracks where those filthy little dwarves skitter about.  Steal me a keg of their Shindigger Stout.  Once I have that keg, you and I will have quite the party, {name}.", progress = "Sometimes I get so bored out here in Tarren Mill I like to open up the formaldehyde jar and let the lovely aroma waft through the air.  Makes Umpi a little nervous though.\n\nSo were you able to get a keg from the Dwarves?  I swear if I have to stare at this deadly elixir without using it on someone for another day I am going to scream.", completion = "Finally!  Now we are ready for action!", objectives = "Bring a keg of Shindigger Stout to Apothecary Lydon in Tarren Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[518] = { id = 518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crown of Will", description = "Mug'Thol and his Crushridge ogres have overrun the ruins of Alterac. It will be hard to inflict any serious punishment upon him without thinning out the ogres' numbers.\n\nAfter softening them up, we'll proceed.\n\nUnderstood? Good. Now go.", progress = "I note that your task is unfinished, {name}. Shall I inform Sharlindra of your ineptitude?", completion = "The snow blooms red with the blood of the ogres, but we cannot cease our efforts until the spirit and numbers of the Crushridge have been crushed and ground into the dirt and snow.", objectives = "Kill 14 Crushridge Maulers for Melisara in Tarren Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[519] = { id = 519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crown of Will", description = "Targ, Muckrake, and Glommus are Mug'Thol's lieutenants. They are loyal to him, though who can say what drives an ogre to loyalty.\n\nBring me their heads, {name}, and then all that will remain is to remove Mug'Thol's head, crown and all.", progress = "I want their heads, {name}, not excuses.", completion = "...and I thought ogres smelled foul enough to begin with.\n\nWhen you bring me Mug'Thol's head, I will have the four of them mounted on pikes above Alterac. A fitting monument to those who go against the Dark Lady's wishes.", objectives = "Kill Targ, Muckrake, and Glommus and bring their heads to Melisara in Tarren Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[520] = { id = 520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crown of Will", description = "With Mug'Thol's lieutenants dead, all that remains is to kill Mug'Thol and retrieve the Crown of Will. I have no doubt he'll be reluctant to part with it. Most likely expecting you, too, given the... departure... of his fellows.\n\nFind Mug'Thol, and deliver his head and the Crown to me. The Crushridge resistance will be at an end.", progress = "Three heads I have, a fourth I need. It will be Mug'Thol's, or it will be yours, {name}. That I promise.", completion = "You have done your duty well, {name}. Mug'Thol's head shall adorn the highest peak of the ruins of Alterac, and the Deathguard will sweep the remnants of the Crushridge into the ground.", objectives = "Kill Mug'Thol, and return his head with the Crown of Will to Melisara in Tarren Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[521] = { id = 521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crown of Will", description = "All that remains is to deliver the Crown of Will to Sharlindra in the Undercity. She will see that it is delivered to Lady Sylvanas. I would warn you against thinking to use it for your own purposes, {name}, Mug'Thol's fate should be illustration enough.", progress = "Yes? Do you have something to report?", completion = "So this is the relic the ogre used to duck the will of the Dark Lady...\n\nStrange that something so simple could wield so great a power. And to fall into as clumsy hands as those. Well done, {name}, I will deliver the crown to Lady Sylvanas, and see that she hears of your accomplishment.", objectives = "Deliver the Crown of Will to Sharlindra in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[522] = { id = 522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assassin's Contract", description = "This is a contract for the assassination of Magistrate Henry Maleb.  It was sealed and stamped in red wax, using a distinctive signet ring.", progress = "You look out of breath!  Do you have something to report?", completion = "<Maleb inspects the contract.>\n\nThat explains the latest attack on Southshore.  The Syndicate must be after me, just as they were the last magistrate!", objectives = "Bring the Assassin's Contract to Magistrate Maleb in Southshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[523] = { id = 523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron's Demise", description = "The contract you recovered was signed by Baron Vardus, a noble of the former kingdom of Alterac, and one known for a cold heart and brutal practices.  I'm not surprised someone like the Baron was behind this.\n\nFind this man.  Find him, and bring him to justice.  He must be among the Syndicate haunts - perhaps at the ruins of Strahnbrad, or perhaps within the valley north of them.", progress = "Baron Vardus cannot think Southshore will allow him to send his thugs against us with impunity.  I want his head!", completion = "Thank you, {name}.  My head rests a little easier, knowing that villain lost his.", objectives = "Bring the Head of Baron Vardus to Magistrate Maleb in Southshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[524] = { id = 524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixir of Agony", description = "Next door the Deathguards are holding a few captured farmers hostage.  High Executor Darthalia suspected one of the military strategists from Stormwind to be hiding out amongst them.  Apparently the military chap was found dead in the Plaguelands last night.  Darthalia, always looking out for me, decided the prisoners would be left to my disposal.\n\nI think it's time we threw those farmers a party.  Sounds like a grand ol' time!\n\nPlace this tainted keg on the rug in their room.  Plagued brew for all!", progress = "A musty smell emanates from the rug.", completion = "You rest the tainted keg on the dusty rug.", objectives = "Place the Tainted Keg on the rug for the captured farmers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
